import { IModel } from './imodel';
import { DateHelper } from '../utils/date-helper';
import { Constants } from './constants.model';

export class ReservationRightTimeRange implements IModel {

    IdObject: any;

    MinutesStart: number;

    MinutesEnd?: number;

    ReservationRight: string;

    ReservationRightId: number;

    constructor(from: number, to: number, reservationRightId: number,  reservationRight?: string, objectId?: number) {
        this.MinutesStart = from;
        this.MinutesEnd = to;
        this.ReservationRight = reservationRight;
        this.ReservationRightId = reservationRightId;

        if (objectId) { this.IdObject = objectId; }
    }

    static create(object: ReservationRightTimeRange): ReservationRightTimeRange {
            const rrtr = new ReservationRightTimeRange(
                object.MinutesStart,
                object.MinutesEnd,
                object.ReservationRightId,
                object.ReservationRight,
                object.IdObject
            );    
            return rrtr;
        }
}

export class ReservationRightOverTime {
    ReservationRights: ReservationRightTimeRange[];

    constructor(reservationRights: ReservationRightTimeRange[])
    {
        this.ReservationRights = reservationRights;
    }

    getReservationRightAtMinutes(minutesFromNow:number): number {
        for(let i = 0; i < this.ReservationRights.length; i++)
        {
            if(i == 0 && minutesFromNow < this.ReservationRights[0].MinutesEnd) return this.ReservationRights[0].ReservationRightId;
            if(i == this.ReservationRights.length - 1) return this.ReservationRights[this.ReservationRights.length - 1].ReservationRightId;
            if(minutesFromNow >= this.ReservationRights[i].MinutesStart && minutesFromNow <= this.ReservationRights[i].MinutesEnd) return this.ReservationRights[i].ReservationRightId;
        }
    }

    getReservationRightAtDate(date:Date): number {
        let resRight = this.getReservationRightAtMinutes(this.getMinutesFromDate(date));
        return resRight;
    }

    getDateTimesRightChanges(): Date[]
    {
        let reservationRightChanges: Date[] = [];

        for(let i = 0; i < this.ReservationRights.length-1; i++)
        {
            let changeDate = new Date(Date.now() + this.ReservationRights[i].MinutesEnd * 60 * 1000);
            // set seconds an miliseconds to 0, and round the minutes down to quarter hours
            changeDate.setMilliseconds(0);
            changeDate.setSeconds(0);
            // if reservation right goes up: round up, if it goes down, round down. Fun fact: the higher the right, the lower the value. Except no rights, that one is negative. 
            let rightsUp = this.ReservationRights[i].ReservationRightId < 0 || this.ReservationRights[i].ReservationRightId > this.ReservationRights[i+1].ReservationRightId;
            let newMinutesValue = rightsUp ? changeDate.getMinutes() + 15 - changeDate.getMinutes() % 15 : changeDate.getMinutes() - changeDate.getMinutes() % 15;
            changeDate.setMinutes(newMinutesValue);

            reservationRightChanges.push(changeDate)
        }

        return reservationRightChanges;
    }

    getReservationRightForTimeSlot(startTimeMinutes: number, endTimeMinutes: number) : number
    {
        startTimeMinutes = startTimeMinutes < 0 ? 0 : startTimeMinutes;
        endTimeMinutes = endTimeMinutes < 0 ? 0 : endTimeMinutes;

        if(startTimeMinutes == 0 && endTimeMinutes == 0)
        {
            return this.ReservationRights[0].ReservationRightId;
        }

        let applicableRights = this.ReservationRights.filter(rr => rr.MinutesStart <= endTimeMinutes && (rr.MinutesEnd >= startTimeMinutes || rr.MinutesEnd == undefined))
        applicableRights.sortByProp(rr => rr.ReservationRightId);
        let result = applicableRights[applicableRights.length - 1].ReservationRightId;
        return result;
    }

    getReservationRightForTimeSlotDates(startTime: Date, endTime: Date) : number
    {
        let startTimeMinutes = this.getMinutesFromDate(startTime);
        let endTimeMinutes = this.getMinutesFromDate(endTime);

        return this.getReservationRightForTimeSlot(startTimeMinutes, endTimeMinutes);
    }

    static createForConstantRight(reservationRightId:number):ReservationRightOverTime
    {
        let fullRange = new ReservationRightTimeRange(0, null, reservationRightId);
        return new ReservationRightOverTime([fullRange]);
    }

    private getMinutesFromDate(date:Date): number {
        return (date.getTime() - Date.now())/(1000 * 60);
    }
}
