import { Component, OnInit, Input } from '@angular/core';
import { BaseInfoComponent } from './base-info.component';
import { BuildingService } from 'src/app/shared/services/rest/building.service';
import { MessageService } from 'src/app/shared/services/message.service';
import { TranslateService } from '@ngx-translate/core';
import { HttpErrorResponse } from '@angular/common/http';
import { Device } from 'src/app/shared/models/device.model';
import { MessageType } from 'src/app/shared/models/message';
import { DeviceService } from 'src/app/shared/services/rest/device.service';
import { StringHelper } from 'src/app/shared/utils/string-helper';
import { HttpHelper } from 'src/app/shared/utils/http-helper';
import { Building } from 'src/app/shared/models/building.model';

@Component({
    selector: 'app-device-info',
    templateUrl: './base-info.component.html',
    styleUrls: ['./base-info.component.scss']
})
export class DeviceInfoComponent extends BaseInfoComponent implements OnInit {

    /**
     * Id of the device to display (required)
     *
     * @type {number}
     * @memberof DeviceInfoComponent
     */
    @Input() deviceId: number;

    constructor(
        private device: DeviceService,
        building: BuildingService,
        messages: MessageService,
        translation: TranslateService
    ) {
        super(building, messages, translation);
    }

    get id(): number {
        return this.deviceId;
    }

    get typePrefix(): string {
        return 'DEVICE';
    }

    ngOnInit(): void {
        if (!this.deviceId) {
            throw new Error('The property "deviceId" is required on DeviceInfoComponent');
        }

        this.loadData();
    }

    protected onLoadData(): void {
        // device
        this.device.get(String(this.deviceId)).toPromise().then(
            (d) => {
                const device = <Device>d;
                // building
                this.building.get(String(device.BuildingId)).toPromise().then(
                    (b) => {
                        const building = Building.create(<Building>b);
                        this.initData(device, building);

                        this.isLoading = false;
                    },
                    () => {
                        this.translation.get('BUILDING_NOT_FOUND', { id: this.deviceId }).subscribe(
                            (text: string) => { this.messages.add(text, MessageType.Error); }
                        );

                        this.isLoading = false;
                    });
            },
            (error: HttpErrorResponse) => {
                if (error.status === 401) {
                    this.hasNoPermission = true;
                } else {
                    this.translation.get('DEVICE_NOT_FOUND', { id: this.deviceId }).subscribe(
                        (text: string) => { this.messages.add(text, MessageType.Error); }
                    );
                }
                this.isLoading = false;
            });
    }

    /**
  * Map loaded data to model
  *
  * @private
  * @param {Room} device
  * @param {Building} building
  * @memberof RoomInfoComponent
  */
    private initData(device: Device, building: Building) {
        this.data = {
            Ressource: {
                Text: [device.Designation, device.Description].filter((e) => e).join('<br>'),
                NumberPersons: null
            },
            Infrastructure: null,
            Remark: StringHelper.nl2br(StringHelper.stringOrEmpty(device.Memo).trim()),
            RessourceUrl: '',
            Site: building.Site,
            Building: {
                Designation: building.Designation,
                Url: building.Url ? HttpHelper.ensureHttpPrefix(building.Url) : null,
                Floor: device.Floor
            },
            Address: [
                StringHelper.stringOrEmpty(building.Address).trim(),
                (StringHelper.stringOrEmpty(building.Zip) + ' ' + StringHelper.stringOrEmpty(building.Location)).trim()
            ].join('<br>')
        };

        this.initMapLink(building.Address, StringHelper.stringOrEmpty(building.Zip), StringHelper.stringOrEmpty(building.Location));
    }
}
