import { Component, OnInit, Input, Output, EventEmitter, TemplateRef, ViewChild, Directive, ElementRef } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgbModal, NgbModalRef, NgbModalOptions } from '@ng-bootstrap/ng-bootstrap';

@Directive({
  selector: '[appModalDialogFocus]'
})
export class ModalDialogFocusDirective implements OnInit {
  constructor(private searchInput: ElementRef) { }

  ngOnInit(): void {
    this.searchInput.nativeElement.focus();
  }
}

@Component({
  selector: 'app-modal-dialog',
  templateUrl: './modal-dialog.component.html'
})
export class ModalDialogComponent implements OnInit {

  /**
   * Reference to the currently open dialog
   *
   * @private
   * @type {NgbModalRef}
   * @memberof ModalDialogComponent
   */
  private _currentModal: NgbModalRef;

  /**
   * Reference to the dialog body (internal)
   *
   * @private
   * @type {TemplateRef<any>}
   * @memberof ModalDialogComponent
   */
  @ViewChild('content') private _content: TemplateRef<any>;

  /**
   * Title of the modal dialog
   *
   * @type {string}
   * @memberof ModalDialogComponent
   */
  @Input() title: string;

  /**
   * Template reference to the body of the dialog (<ng-template>)
   *
   * @type {TemplateRef<any>}
   * @memberof ModalDialogComponent
   */
  @Input() body: TemplateRef<any>;

  /**
   * text of cancel button (secondary-color)
   *
   * @type {string}
   * @memberof ModalDialogComponent
   */
  @Input() cancelButton: string;

  /**
   * text of negative button (danger-color)
   *
   * @type {string}
   * @memberof ModalDialogComponent
   */
  @Input() negativeButton: string;

  /**
   * text of positive button (default-color)
   *
   * @type {string}
   * @memberof ModalDialogComponent
   */
  @Input() positiveButton: string;

  /**
   * Set to true to disable positiveButton
   *
   * @type {string}
   * @memberof ModalDialogComponent
   */
  @Input() positiveButtonDisabled: string;

  /**
   * True to display cancel button (default true)
   *
   * @memberof ModalDialogComponent
   */
  @Input() showCancel = true;

  /**
   * True to display positive button (default true)
   *
   * @memberof ModalDialogComponent
   */
  @Input() showPositive = true;

  /**
   * True to display negative button (default false)
   *
   * @memberof ModalDialogComponent
   */
  @Input() showNegative = false;

  /**
   * Show backdrop or not. Set `static` to make disable closing on click (default true)
   *
   * @memberof ModalDialogComponent
   */
  @Input() backdrop: boolean | 'static' = true;

  /**
   * Set to 'large' or 'small' to resize, '' (empty) for default
   *
   * @memberof ModalDialogComponent
   */
  @Input() size: 'lg' | 'sm' | null = null;

  /**
   * Cancel event
   *
   * @memberof ModalDialogComponent
   */
  @Output() cancel = new EventEmitter<void>();

  /**
   * Negative event
   *
   * @memberof ModalDialogComponent
   */
  @Output() negative = new EventEmitter<void>();

  /**
   * Positive event
   *
   * @memberof ModalDialogComponent
   */
  @Output() positive = new EventEmitter<void>();

  /**
   * After opening of dialog event
   *
   * @memberof ModalDialogComponent
   */
  @Output() afterOpen = new EventEmitter<void>();

  /**
   * Creates an instance of ModalDialogComponent.
   * @param {NgbModal} modalService
   * @param {TranslateService} translate
   * @memberof ModalDialogComponent
   */
  constructor(private modalService: NgbModal, private translate: TranslateService) { }

  /**
   * init component
   *
   * @memberof ModalDialogComponent
   */
  ngOnInit() {
    this.validateSettings();

    if (!this.cancelButton) {
      this.translate.get('BTN_CANCEL').subscribe((val) => { this.cancelButton = val; });
    }
    if (!this.negativeButton) {
      this.translate.get('BTN_NO').subscribe((val) => { this.negativeButton = val; });
    }
    if (!this.positiveButton) {
      this.translate.get('BTN_OK').subscribe((val) => { this.positiveButton = val; });
    }
  }

  /**
   * Ensure required minimum is defined
   *
   * @private
   * @memberof ModalDialogComponent
   */
  private validateSettings() {
    if (this.title === null || this.body === null) {
      throw new Error('Please provide title and body property on modal-dialog');
    }
    if (this.positive === null && this.negative === null) {
      throw new Error('Please provide positive or negative property on modal-dialog');
    }
  }

  /**
   * Run the dialog
   *
   * @param {*} content
   * @memberof ModalDialogComponent
   */
  openModal() {
    const options: NgbModalOptions = { ariaLabelledBy: this.title, size: this.size, backdrop: this.backdrop };

    this._currentModal = this.modalService.open(this._content, options);

    this._currentModal.result.then(
      (_) => this.onModalClose(),
      (reason) => this.onModalDismiss(reason)
    );

    this.afterOpen.emit();
  }

  /**
   * Close the dialog
   * @param result
   */
  closeModal(result: any) {
    if (this._currentModal) {
      this._currentModal.close(result);
    }
  }

  /**
   * Handle positive
   *
   * @memberof ModalDialogComponent
   */
  onModalClose() {
    this.positive.emit();
  }

  /**
   * Handle dismiss (cancel or negative)
   *
   * @param {*} reason
   * @returns
   * @memberof ModalDialogComponent
   */
  onModalDismiss(reason: any) {
    switch (reason) {
      case 'cancel':
      case 0: // click into the wild
      case 1: // escape key
        return this.cancel.emit();
      case 'negative':
        return this.negative.emit();
      default:
        throw new Error('unknown dismiss reason: ' + reason);
    }
  }

  /**
   * return true if any button is displayed
   *
   * @readonly
   * @type {boolean}
   * @memberof ModalDialogComponent
   */
  get showFooter(): boolean {
    return this.showCancel || this.showPositive || this.showNegative;
  }
}
