import { Injectable, EventEmitter } from '@angular/core';
import { IMessage, MessageType } from '../models/message';
import { AppConfigService } from './app-config.service';
import { StringHelper } from '../utils/string-helper';

@Injectable({
  providedIn: 'root'
})
export class MessageService {

  /**
   * Current messages
   *
   * @type {IMessage[]}
   * @memberof MessageService
   */
  private _messages: IMessage[] = [];

  /**
   * Message EventEmitter
   *
   * @memberof MessageService
   */
  public messages = new EventEmitter<IMessage[]>(true);

  /**
   * Creates an instance of MessageService.
   * @param {AppConfigService} appConfig
   * @memberof MessageService
   */
  constructor() {
  }

  /**
   * Create a pseudo Guid
   *
   * @private
   * @static
   * @returns {string}
   * @memberof MessageService
   */
  private static createMessageId(): string {
    const seconds = Math.floor((new Date()).getTime() / 1000);
    return String(seconds) + '-' + StringHelper.getRandom();
  }

  /**
   * add a new message
   *
   * @param {string} text
   * @param {MessageType} type
   * @param {string} [id=null]
   * @memberof MessageService
   */
  add(text: string, type: MessageType, id: string = null): void | never {
    // message
    if (type !== MessageType.Debug || AppConfigService.settings.debug) {
      if (id === null) {
        this._messages.push({ id: MessageService.createMessageId(), text: text, type: type });
      } else if (this._messages.filter((msg) => msg.id === id).length === 0) {
        // add if no already exists
        this._messages.push({ id: id, text: text, type: type });
      }
      this.broadcast();
    }

    // console output
    if (AppConfigService.settings.debug) {
      this.writeToConsole({ id: id, text: text, type: type });
    }

  }

  /**
   * Remove any message by id
   *
   * @param {string} messageId
   * @memberof MessageService
   */
  remove(messageId: string) {
    const indexes: number[] = [];

    this._messages.forEach((message, i) => {
      if (message.id === messageId) {
        indexes.push(i);
      }
    });

    indexes.forEach(element => {
      this._messages.splice(element, 1);
    });

    this.broadcast();
  }

  /**
   * Clear all messages
   *
   * @memberof MessageService
   */
  clear() {
    this._messages = [];
    this.broadcast();
  }

  /**
   * Emitts the current messages to the listeners
   *
   * @private
   * @memberof MessageService
   */
  private broadcast() {
    this.messages.next(this._messages);
  }

  /**
   * Write messages to console
   *
   * @private
   * @param {IMessage} message
   * @memberof MessageService
   */
  private writeToConsole(message: IMessage): void {
    switch (message.type) {
      case MessageType.Error:
        console.error(message.text);
        break;
      case MessageType.Waning:
        console.warn(message.text);
        break;
      default:
        console.log(message.text);
    }
  }
}
