import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders, HttpErrorResponse, HttpResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';
import { AppConfigService } from '../app-config.service';
import { Constants } from '../../models/constants.model';
import { AuthorizationService } from '../authorization.service';
import { MessageService } from '../message.service';
import { MessageType } from '../../models/message';
import { CacheService } from '../cache.service';
import { ArrayHelper } from '../../utils/array-helper';
import { StringHelper } from '../../utils/string-helper';
import { HttpHelper } from '../../utils/http-helper';
import { UrlHelper } from '../../utils/url-helper';
import { AvailableRoom } from '../../models/available-room';
import { AvailableDevice } from '../../models/available-device';
import { StatusId } from '../../models/status-id';
import { IStatusInfo } from 'src/app/modules/room-reservation/components/room-allocation-table/room-allocation-table.component';
import { TranslateService } from '@ngx-translate/core';
import { LanguageService } from '../language.service';

@Injectable({
  providedIn: 'root'
})
export abstract class BaseService<TEntity> {

  /**
   * Request-ContentType
   *
   * @protected
   * @memberof BaseService
   */
  protected contentType = Constants.ContentType.JSON;

  /**
   * Service required authentication
   *
   * @protected
   * @memberof BaseService
   */
  protected get authorizationType() {
    return AuthorizationType.Login;
  }

  /**
   * Base-url of rest-service
   *
   * @private
   * @type {string}
   * @memberof BaseService
   */
  protected apiBaseUrl: string;

  /**
   * Indicates when a login-redirect is pending
   *
   * @protected
   * @memberof BaseService
   */
  protected isRedirectPending = false;

  /**
   * Http-request options
   *
   * @private
   * @type {*}
   * @memberof BaseService
   */
  private httpOptions: any;

  /**
   * Number of retries before failing with a request
   *
   * @private
   * @type {number}
   * @memberof BaseService
   */
  private numRetry: number;

  constructor(
    private http: HttpClient,
    private authorization: AuthorizationService,
    private messages: MessageService,
    protected cache: CacheService
  ) {
    this.apiBaseUrl = UrlHelper.trimUrl(AppConfigService.settings.apiUrl);
    this.numRetry = AppConfigService.settings.debug ? 0 : 2;
    this.loadHttpOptions();
  }

  /**
   * Uri of the rest-endpoint
   *
   * @protected
   * @abstract
   * @type {string}
   * @memberof BaseService
   */
  protected abstract readonly endpointUri: string;

  abstract getAll(): Observable<TEntity[]>;

  abstract get(id: string): Observable<any>;

  abstract add(entity: TEntity, headers: IKeyValuePair<string, string>[]): Observable<any>;

  abstract update(entity: TEntity): Observable<any>;

  abstract delete(id: string): Observable<{}>;

  protected getAllRequest(url: string = null, params: IKeyValuePair<string, string>[] = null) {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    return this.http.get<TEntity[]>(this.getFullUrl(endpoint, null, params), this.httpOptions)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity[]>(`GET: ${endpoint}`))
      );
  }

  protected getRequest<TResult>(id: string, url: string = null, params: IKeyValuePair<string, string>[] = null): any {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    return this.http.get<TResult>(this.getFullUrl(endpoint, id, params), this.httpOptions)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity>(`GET: ${endpoint}`))
      );
  }

  protected getRequestCustom<TResult>(url: string = null): any {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    return this.http.get<TResult>(url, this.httpOptions)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity>(`GET-Custom: ${url}`))
      );
  }

  protected addRequest(url: string = null, entity: TEntity, headers: IKeyValuePair<string, string>[]): Observable<any> {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    const options = headers ? this.mergeHeaders(this.httpOptions, headers) : this.httpOptions;
    options.observe = 'response';
    return this.http.post<HttpResponse<TEntity>>(this.getFullUrl(endpoint, null), entity, options)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity>(`POST: ${endpoint}`))
      );
  }

  protected updateRequest(id: string, url: string = null, entity: TEntity, headers: IKeyValuePair<string, string>[]): Observable<any> {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    const options = headers ? this.mergeHeaders(this.httpOptions, headers) : this.httpOptions;
    options.observe = 'response';
    return this.http.put<HttpResponse<TEntity>>(this.getFullUrl(endpoint, id), entity, this.httpOptions)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity>(`PUT: ${endpoint}`))
      );
  }

  protected patchRequest(id: string, url: string = null, entity: TEntity, headers: IKeyValuePair<string, string>[]): Observable<any> {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    const options = headers ? this.mergeHeaders(this.httpOptions, headers) : this.httpOptions;
    options.observe = 'response';
    return this.http.patch<HttpResponse<TEntity>>(this.getFullUrl(endpoint, id), entity, this.httpOptions)
      .pipe(
        retry(this.numRetry),
        catchError(this.handleError<TEntity>(`PATCH: ${endpoint}`))
      );
  }

  protected deleteRequest(id: string, url: string = null): Observable<{}> {
    if (this.shouldReturnEmpty) {
      return this.emptyResponse;
    }

    const endpoint = url == null ? this.endpointUri : url;
    return this.http.delete(this.getFullUrl(endpoint, id), this.httpOptions)
      .pipe(
        catchError(this.handleError<TEntity>(`DELETE: ${endpoint}`))
      );
  }

  /**
   * Returns true if any operation is pending, which should prevent http-respones-handling
   *
   * @readonly
   * @private
   * @type {boolean}
   * @memberof BaseService
   */
  private get shouldReturnEmpty(): boolean {
    this.ensureLogin();
    return this.isRedirectPending;
  }

  /**
   * Returns an empty observeable
   *
   * @readonly
   * @private
   * @type {Observable<any>}
   * @memberof BaseService
   */
  private get emptyResponse(): Observable<any> {
    return new Observable();
  }

  /**
   * Handle request-errors
   *
   * @private
   * @template T
   * @param {string} [operation='unknown']
   * @param {T} [result]
   * @returns
   * @memberof BaseService
   */
  private handleError<T>(operation = 'unknown') {
    return (error: HttpErrorResponse): Observable<T> => {
      if (error.error instanceof ErrorEvent) {
        // A client-side or network error occurred.
        this.messages.add(operation + ': ' + error.error.message, MessageType.Error);
      } else {
        // The backend returned an unsuccessful response code.
        const err = 'Error on http-request for ' + error.url + ': ' + error.status + ' ' + HttpHelper.getStatusText(error.status);
        this.messages.add(`${operation} => ${err}`, MessageType.Debug);
      }

      return throwError(error);
    };
  }

  /**
   * Set endpoint headers
   *
   * @private
   * @returns {(void | never)}
   * @memberof BaseService
   */
  private loadHttpOptions(): void | never {
    const headers = {};
    headers[Constants.Header.Request.ContentType] = this.contentType;

    if (this.authorizationType !== AuthorizationType.None) {
      this.ensureLogin();
      // set header
      headers[Constants.Header.Request.Authorization] = this.authorization.getAuthorizationHeaderValue();
    }

    this.httpOptions = {
      headers: new HttpHeaders(headers)
    };
  }

  /**
   * Starts login if required
   *
   * @private
   * @return {*}  {(void | never)}
   * @memberof BaseService
   */
  private ensureLogin(): void | never {
    if (this.authorizationType === AuthorizationType.None || this.authorization.isAuthorized() || this.isRedirectPending) { return; }

    // redirect log oauth
    this.isRedirectPending = true;
    switch (this.authorizationType) {
      case AuthorizationType.Anonymous:
        this.authorization.logInAnonymous();
        break;
      case AuthorizationType.Login:
        this.authorization.logIn();
        break;
      default:
        this.messages.add('authorization for type "' + this.authorization + '" not implemented', MessageType.Debug);
    }
  }

  /**
   * Returns the full qualified url for an endpoint
   *
   * @private
   * @param {string} url
   * @param {IKeyValuePair[]} [params=null]
   * @returns {string}
   * @memberof BaseService
   */
  private getFullUrl(url: string, id: string, params: IKeyValuePair<string, string>[] = null): string {
    let result = this.apiBaseUrl + '/' + url + '/';
    // let result = this.apiBaseUrl + '/' + url + (url.includes('/') ? '' : '/');

    if (StringHelper.hasAny(id)) {
      result += id;
    }

    if (ArrayHelper.hasAny(params)) {
      result += '?' + params
        .filter(kv => !StringHelper.isNullOrEmpty(kv.value))
        .map(kv => `${kv.key}=${encodeURIComponent(kv.value)}`)
        .join('&');
    }

    return result;
  }

  private mergeHeaders(httpOptions: any, additionalHeaders: IKeyValuePair<string, string>[]): any {
    const keyValue = {};
    // existing headers
    httpOptions.headers.forEach((key: string, value: string[]) => { keyValue[key] = value[0]; });
    // additional header
    additionalHeaders.forEach(kv => { keyValue[kv.key] = kv.value; });
    // set headers
    httpOptions.headers = new HttpHeaders(keyValue);

    return httpOptions;
  }

  // TODO: reduce to minimal func calls, model return data
  public getReservabilityToken(room: AvailableRoom | AvailableDevice, searchDate: Date) {
      type AvailableResource = AvailableRoom | AvailableDevice;

    const pipe = [
      // room unavailable: 0 - 3
      (r: AvailableResource) => r.StatusId === (StatusId.rrGesperrtBis as number) && r.StatusDate >= searchDate,
      (r: AvailableResource) => r.StatusId === (StatusId.rrReservierbarBis as number) && new Date(r.StatusDate).setHours(0,0,0,0) < new Date(searchDate).setHours(0,0,0,0),
      (r: AvailableResource) => r.StatusAllowOccupation !== true,
      (r: AvailableResource) => r.IsWorkingDay !== true,

      // rights available: 4 - 6
      (r: AvailableResource) => r.ReservationRightId === Constants.ReservationsRecht.Reservable,
      (r: AvailableResource) => r.ReservationRightId === Constants.ReservationsRecht.ProvReservable,
      (r: AvailableResource) => r.ReservationRightId === Constants.ReservationsRecht.Requestable,

      // rights unavailable: 7
      (r: AvailableResource) => r.ReservationRightId === Constants.ReservationsRecht.Visible,
    ];

    const appliedRule = pipe.findIndex(p => p(room));

    if (appliedRule === -1 || appliedRule > 7) {
      throw new Error('Mismatch: ' + room);
    }

    if (appliedRule < 4) {
      return { isRessourceAvailable: false, isBookingAllowed: false, actionLabel: null };
    }

    if (appliedRule < 7) {
      return { isRessourceAvailable: true, isBookingAllowed: true, actionLabel: appliedRule !== 6 ? 'RESERVE' : 'REQUEST' };
    }

    if (appliedRule === 7) {
      return { isRessourceAvailable: true, isBookingAllowed: false, actionLabel: null };
    }
  }

  protected getStatusWarning(statusInfo: IStatusInfo, searchDate:Date,  resourceLabel: string, translation: TranslateService, language: LanguageService): Observable<string>
  {
    let tempSearchDate = new Date(searchDate);

    // status
    switch (statusInfo.StatusId) {
      case StatusId.rrGesperrt:
        return translation.get('RESSOURCE_STATE_CLOSED', {resourceLabel: resourceLabel});
      case StatusId.rrGesperrtBis:
        if (new Date(tempSearchDate.setHours(0,0,0,0)) <= new Date(statusInfo.StatusDate)) {
          return translation.get('RESSOURCE_STATE_CLOSED_UNTIL', { resourceLabel: resourceLabel, date: language.formatDate(statusInfo.StatusDate) });
        }
        break;
      case StatusId.rrReservierbarBis:
        if (new Date(tempSearchDate.setHours(0,0,0,0)) > new Date(statusInfo.StatusDate)) {
          return translation.get('RESSOURCE_STATE_OPEN_UNTIL', { resourceLabel: resourceLabel, date: language.formatDate(statusInfo.StatusDate) });
        }
        break;
      case StatusId.rrReservierbar: // ok
        break;
      default:
        console.warn(`status unknown: (${statusInfo.StatusId} - ${statusInfo.Status})`);
        break;
    }

    return null;
  }

  public checkOccupationStatusReservationAndWorkday(searchDate:Date, StatusAllowOccupation: boolean, IsWorkingDay: boolean, ReservationRightId: number, resourceLabel: string, resourceId: number, translation: TranslateService, language: LanguageService)
  {
      // c)	hat das Attribut «Belegung erlaubt» inaktiviert:
      if (!StatusAllowOccupation) {
        return translation.get('RESSOURCE_STATE_CLOSED', {resourceLabel: resourceLabel});
      }
  
      // reservationstyp
      switch (ReservationRightId) {
        case Constants.ReservationsRecht.Reservable:
          // ok
          break;
        case Constants.ReservationsRecht.ProvReservable:
          return translation.get('RESSOURCE_PERMISSION_PROV');
        case Constants.ReservationsRecht.Requestable:
          return translation.get('RESSOURCE_PERMISSION_REQUEST');
        case Constants.ReservationsRecht.Visible:
        case Constants.ReservationsRecht.None:
          return translation.get('RESSOURCE_NO_PERMISSION_OCCUPY');
        default:
          let errorText = `invalid reservation type: ${ReservationRightId} for ${resourceId}`
          console.log(errorText);
          throw Error(errorText);
      }
  
      // keine Arbeitszeit
      if (!IsWorkingDay) {
        return translation.get('RESSOURCE_STATE_NO_WORKDAY', { resourceLabel: resourceLabel, date: language.formatDate(searchDate)});
      }

      // date in the past? Method used for overview and similar, there this is the least useful information
      let tempSearchDate = new Date(searchDate);
      if(tempSearchDate.setHours(0,0,0,0) < new Date().setHours(0,0,0,0)) // is the Date in the past?
      {
        return translation.get('RESSOURCE_STATE_DATE_IN_PAST', {date: language.formatDate(searchDate)});
      }
  }

}

/**
 * Key/Value pair interface
 *
 * @interface IKeyValuePair
 */
export interface IKeyValuePair<TKey, TValue> {
  // todo tosc: move
  key: TKey;
  value: TValue;
}

export enum AuthorizationType {
  // No token required
  None = 1,
  // Anonymous token in scope Public
  Anonymous = 2,
  // Authenticate
  Login = 3,
}
