import { FormGroup, AbstractControl } from '@angular/forms';

/**
 * Provides typed abstraction for Angular FormGroup
 *
 * @export
 * @class SearchForm
 * @template TForm
 */
export class SearchForm<TForm> {

    /**
     * Angulars FormGroup instance
     *
     * @private
     * @type {FormGroup}
     * @memberof SearchForm
     */
    private readonly form: FormGroup;

    /**
     * Converts 'value' to string
     *
     * @private
     * @param {*} value
     * @returns {string}
     * @memberof SearchForm
     */
    private static stringify(value: any): string {
        if (value instanceof Date) {
            return (value as Date).toISOString();
        }

        if (typeof value === 'boolean') {
            return value ? '1' : '';
        }

        return String(value);
    }

    /**
     * FormGroup instance
     *
     * @readonly
     * @type {FormGroup}
     * @memberof SearchForm
     */
    get formGroup(): FormGroup {
        return this.form;
    }

    /**
     * valid property of the FormGroup
     *
     * @readonly
     * @type {boolean}
     * @memberof SearchForm
     */
    get valid(): boolean {
        return this.form.valid;
    }

    /**
     * dirty property of the FormGroup
     *
     * @readonly
     * @type {boolean}
     * @memberof SearchForm
     */
    get dirty(): boolean {
        return this.form.dirty;
    }

    /**
     * Creates an instance of SearchForm.
     * @param {FormGroup} form
     * @memberof SearchForm
     */
    constructor(form: FormGroup) {
        this.form = form;
    }

    /**
     * Returns the AbstractControl of the field
     *
     * @param {keyof TForm} field
     * @returns {AbstractControl}
     * @memberof SearchForm
     */
    public get(field: keyof TForm): AbstractControl {
        const element = this.form.get(String(field));
        if (element === undefined) {
            throw new Error('Field ' + String(field) + ' is not defined on SearchForm');
        }
        return element;
    }

    /**
     * Sets the value of the field
     *
     * @param {keyof TForm} field
     * @param {(string | number | Date | boolean)} value
     * @memberof SearchForm
     */
    public setValue(field: keyof TForm, value: string | number | Date | boolean): void {
        this.get(field).setValue(SearchForm.stringify(value));
    }

    /**
     * Patches the value of the field
     *
     * @param {keyof TForm} field
     * @param {(string | number | Date | boolean)} value
     * @memberof SearchForm
     */
    public patchValue(field: keyof TForm, value: string | number | Date | boolean): void {
        this.get(field).patchValue(SearchForm.stringify(value));
    }

    /**
     * Returns the value of the field (always a string)
     *
     * @param {keyof TForm} field
     * @returns {string}
     * @memberof SearchForm
     */
    public getValue(field: keyof TForm): string {
        return this.get(field).value;
    }

    /**
     * Enable a field
     *
     * @param {keyof TForm} field
     * @memberof SearchForm
     */
    public enable(field: keyof TForm): void {
        this.get(field).enable();
    }

    /**
     * Disable a field
     *
     * @param {keyof TForm} field
     * @memberof SearchForm
     */
    public disable(field: keyof TForm): void {
        this.get(field).disable();
    }
}
