export class OAuthToken {

    static EXPIRATION = 'exp';

    access_token: string;
    refresh_token: string;
    token_type: string;
    expires_in: number;

    /**
     * extracts the expiration in milliseconds from the accessToken
     *
     * @returns {number}
     * @memberof OAuthToken
     */
    public getExpirationMilliseconds(): number {

        // decodes a base64 encoded utf-8 string
      var decodeBase64Url = (base64UrlStr) => {
          // convert from base64Url to base64
          let base64Str = base64UrlStr.replace(/-/g, "+").replace(/_/g, "/").replace(/\s/g, "");
          // decode base64 string
          let binary = atob(base64Str);
          // convert to bytes
          let bytes = new Uint8Array(binary.length);
          for (let i = 0; i < binary.length; i++) {
            bytes[i] = binary.charCodeAt(i);
          }
          // decode bytes as utf-8
          return new TextDecoder("utf8").decode(bytes);
        };

        const parts = this.access_token.split('.');
        const body = JSON.parse(decodeBase64Url(parts[1]));
        const expiration = body[OAuthToken.EXPIRATION];

        if (expiration !== null && expiration !== '') {
            const num = Number(expiration);
            if (num !== Number.NaN) {
                return num;
            }
        }
        return null;
    }
}
