import { Injectable } from '@angular/core';
import * as cryptoJs from "crypto-js";
import { AppConfigService } from './app-config.service';
import { StorageService } from './storage.service';
import { Constants } from '../models/constants.model';
import { OAuthToken } from '../models/oauth-token.model';
import { MessageType } from '../models/message';
import { MessageService } from './message.service';
import { UrlHelper } from '../utils/url-helper';
import { SpinnerService } from './spinner.service';
import { StringHelper } from '../utils/string-helper';
import { HtmlHelper } from '../utils/html-helper';

@Injectable({
  providedIn: 'root'
})
export class AuthorizationService {

  /**
   * Url of the OAuthServer (trimmed)
   *
   * @private
   * @type {string}
   * @memberof AuthorizationService
   */
  private oauthUrl: string;

  static loginInProgress: boolean = false;

  constructor(
    private storage: StorageService,
    private messages: MessageService,
    private spinner: SpinnerService,
  ) {
    this.oauthUrl = UrlHelper.trimUrl(AppConfigService.settings.oauthUrl);
  }

  /**
   * Returns true if the client has a valid token
   *
   * @returns {boolean}
   * @memberof AuthorizationService
   */
  isAuthorized(): boolean {
    const expire = this.storage.getTokenExpire();
    return this.storage.getLoginToken() !== null && expire != null && expire > Math.round(new Date().getTime() / 1000);
  }

  /**
   * Invoke login-process
   *
   * @memberof AuthorizationService
   */
  logIn(): void {

    if (AuthorizationService.loginInProgress) return;

    AuthorizationService.loginInProgress = true;
    const codeChallenge = this.beforeLogin();
    window.location.href = this.getLoginRedirectUri(codeChallenge);
  }

  /**
   * Invoke anonymous login-process
   *
   * @memberof AuthorizationService
   */
  logInAnonymous(): void {
    this.beforeLogin(false);
    window.location.href = this.getAnonymousRedirectUri();
  }

  /**
   * Invoke token refresh by form post
   *
   * @memberof AuthorizationService
   */
  refreshToken(cultureInfo: string = null): void {
    const codeChallenge = this.beforeLogin();

    const formAction = AppConfigService.oauthUrl + '/Authorization/RefreshPublic';
    const htmlForm = HtmlHelper.createHiddenForm(
      formAction,
      [
        { key: "RefreshToken", value: this.storage.getRefreshToken() },
        { key: "CultureInfo", value: cultureInfo ? cultureInfo : this.storage.getUiCulture() },
        { key: "ApplicationScope", value: AppConfigService.settings.appScope },
        { key: "moduleRedirectUrl", value: AppConfigService.settings.webBaseUrl },
        { key: Constants.RequestBodyParams.ResponseType, value: "code" },
        { key: Constants.RequestBodyParams.CodeChallenge, value: codeChallenge },
        { key: Constants.RequestBodyParams.CodeChallengeMethod, value: "S256" }
      ]);

    HtmlHelper.appendToBody(htmlForm);
    htmlForm.submit();
  }

  /**
   * Invoke logout-precess
   *
   * @memberof AuthorizationService
   */
  logOut(): void {
    const token = this.storage.getLoginToken();
    this.beforeLogout();

    const formAction = AppConfigService.oauthUrl + '/Authorization/' + AppConfigService.settings.instanceId + '/Logout';
    const htmlForm = HtmlHelper.createHiddenForm(
      formAction,
      [{ key: Constants.RequestBodyParams.AccessToken, value: token }]
    );
    HtmlHelper.appendToBody(htmlForm);
    htmlForm.submit();
  }

  /**
   * Process redirect after authorization on OAuth server
   *
   * @param {OAuthToken} oAuthToken
   * @memberof AuthorizationService
   */
  safeLoginAndRedirect(oAuthToken: OAuthToken) {
    // save tokens
    this.storage.setLoginToken(oAuthToken.access_token);
    this.storage.setRefreshToken(oAuthToken.refresh_token);
    this.storage.setTokenExpire(oAuthToken.getExpirationMilliseconds());

    // redirect to pre-login uri
    const redirect = this.storage.getEntryPointUrl();
    if (redirect !== null) {
      this.storage.setEntryPointUrl(null);
      window.location.href = redirect;
    } else {
      window.location.href = AppConfigService.settings.webBaseUrl;
    }
  }

  /**
   * Compose value for http-header 'CLX-Authorization'
   *
   * @returns {string}
   * @memberof AuthorizationService
   */
  public getAuthorizationHeaderValue(): string {
    const tokenType = Constants.UrlParams.TokenType + '=' + AppConfigService.settings.tokenType;
    const accessToken = Constants.UrlParams.AccessToken + '=' + this.storage.getLoginToken();
    return [tokenType, accessToken].join(', ');
  }

  /**
   * Returns the url parameters for Authorization Code Flow with PKCE
   *
   * @private
   * @param {string} codeChallenge
   * @return {string}
   * @memberof AuthorizationService
   */
  private getAuthCodeArgs(codeChallenge: string): string {
    return `response_type=code&code_challenge_method=S256&code_challenge=${codeChallenge}`;
  }

  /**
   * Compose OAuth-login uri
   *
   * @private
   * @param {string} codeChallenge
   * @returns {string}
   * @memberof AuthorizationService
   */
  private getLoginRedirectUri(codeChallenge: string): string {
    return this.oauthUrl
      + '/Authorization/'
      + AppConfigService.settings.instanceId
      + '/Login?client_id=' + AppConfigService.settings.clientId
      + '&redirect_uri=' + encodeURIComponent(AppConfigService.settings.webBaseUrl)
      + '&culture_info=' + this.storage.getUiCulture()
      + '&application_scope=' + AppConfigService.settings.appScope
      + '&' + this.getAuthCodeArgs(codeChallenge);
  }

  /**
   * Compose OAuth-login uri for anonymous token
   *
   * @private
   * @returns {string}
   * @memberof AuthorizationService
   */
  private getAnonymousRedirectUri(): string {
    if (AppConfigService.settings.appScope !== 'Public') {
      const msg = 'appconfig.json: appScope "Public" is required to use anonymous login';
      this.messages.add(msg, MessageType.Error);
      throw new Error(msg);
    }

    return this.oauthUrl
      + '/Authorization/'
      + AppConfigService.settings.instanceId
      + '/Token?client_id=' + AppConfigService.settings.clientId
      + '&redirect_uri=' + encodeURIComponent(AppConfigService.settings.webBaseUrl)
      + '&culture_info=' + this.storage.getUiCulture();
  }

  /**
   * Handle login-prerequisits
   *
   * @private
   * @param {boolean}
   * @returns {string|null} PKCE code_challenge
   * @memberof AuthorizationService
   */
  private beforeLogin(usePkce: boolean = true): string {
    this.spinner.waitFor(new Promise(() => {/* show spinner forever*/ }));

    // save current uri to redirect after login (only if empty)
    if (!this.storage.getEntryPointUrl()) {
      this.storage.setEntryPointUrl(window.location.href);
    }

    if (!usePkce) return null;

    //PKCE
    const code_verifier = this.createCodeVerifier();
    this.storage.setPkceCodeVerifier(code_verifier);

    return this.createSha256CodeChallenge(code_verifier);
  }

  /**
   * Handle logout-prerequisits
   *
   * @private
   * @memberof AuthorizationService
   */
  private beforeLogout() {
    this.storage.clearAll();
  }

  /**
   * Creates a random code_verifier
   *
   * @private
   * @return {string}
   * @memberof AuthorizationService
   */
  private createCodeVerifier(): string {
    const bytes = new Uint8Array(48);
    window.crypto.getRandomValues(bytes);
    return StringHelper.base64UrlEncodeBytes(bytes);
  }

  /**
   * Creates a SHA256 hash from given codeVerifier
   *
   * @private
   * @param {string} codeVerifier
   * @return {string} base64url encoded sha256 hash
   * @memberof AuthorizationService
   */
  private createSha256CodeChallenge(codeVerifier: string): string {
    const bytes = cryptoJs.SHA256(codeVerifier);
    const base64String = cryptoJs.enc.Base64.stringify(bytes);
    return StringHelper.convertBase64ToBase64Url(base64String);
  }

}
