import { Occupancy } from './occupancy';
import { DateHelper } from '../utils/date-helper';
import { Constants } from './constants.model';
import { IDisplayItem, IStatusInfo } from 'src/app/modules/room-reservation/components/room-allocation-table/room-allocation-table.component';
import { RoomScheduleComponent } from 'src/app/modules/room-reservation/components/room-schedule/room-schedule.component';
import { Observable } from 'rxjs';
import { ReservationRightOverTime, ReservationRightTimeRange } from './reservation-right-time-range';

export class AvailableRoom {

    Room: string;

    RoomId: number;

    RoomType: string;

    RoomTypeId: number;

    Occupancies: Occupancy[];

    IsAvailable: boolean;

    IsBookable: boolean;

    ReservationRight: string;

    ReservationRightId: number;

    ReservationRightTimeRanges: ReservationRightTimeRange[];

    Status: string;

    StatusDate: Date;

    StatusId: number;

    StatusAllowOccupation: boolean;

    IsWorkingDay: boolean;

    BuildingId: number;

    Building: string;

    Floor: string;

    NumberPersons: number;

    // internal props
    warning: string;

    meta: {
        isRessourceAvailable: boolean;
        isBookingAllowed: boolean;
        actionLabel: string;
    }

    /**
     * Map untyped representation into new typed instance
     *
     * @static
     * @param {*} object
     * @returns {AvailableRoom}
     * @memberof AvailableRoom
     */
    public static create(object: AvailableRoom): AvailableRoom {
        const instance = new AvailableRoom();
        instance.Room = object.Room;
        instance.RoomId = object.RoomId;
        instance.RoomType = object.RoomType;
        instance.RoomTypeId = object.RoomTypeId;
        instance.Occupancies = object.Occupancies.map(o => Occupancy.create(o));
        instance.IsAvailable = object.IsAvailable;
        instance.IsBookable = object.IsBookable;
        instance.ReservationRight = object.ReservationRight;
        instance.ReservationRightId = object.ReservationRightId;
        instance.ReservationRightTimeRanges = object.ReservationRightTimeRanges ? object.ReservationRightTimeRanges.map(rrtr => ReservationRightTimeRange.create(rrtr)) : null;
        instance.Status = object.Status;
        instance.StatusDate = DateHelper.parseDateString(object.StatusDate);
        instance.StatusId = object.StatusId;
        instance.IsWorkingDay = object.IsWorkingDay;
        instance.StatusAllowOccupation = object.StatusAllowOccupation;
        instance.BuildingId = object.BuildingId;
        instance.Floor = object.Floor;
        instance.Building = object.Building;
        instance.NumberPersons = object.NumberPersons;

        return instance;
    }

    /**
     * Map AvailableRoom to IDisplayItem
     *
     * @static
     * @param {AvailableRoom} ar
     * @param {Observable<string>} text
     * @param {Date} minDate
     * @param {Date} maxDate
     * @returns {IDisplayItem}
     * @memberof AvailableRoom
     */
    public static mapDisplayItem(ar: AvailableRoom, text: Observable<string>, minDate: Date, maxDate: Date): IDisplayItem {
        const statusInfo: IStatusInfo = {
                    Status: ar.Status,
                    StatusDate: ar.StatusDate,
                    StatusId: ar.StatusId,
                };

        let resRights: ReservationRightOverTime;
        resRights = ar.ReservationRightTimeRanges ? new ReservationRightOverTime(ar.ReservationRightTimeRanges) : ReservationRightOverTime.createForConstantRight(ar.ReservationRightId);

        const item: IDisplayItem = {
            resourceId: ar.RoomId,
            designation: ar.Room,
            warning: ar.warning,
            statusInfo: statusInfo,
            isBookable: ar.StatusAllowOccupation
                && ar.IsBookable && ar.IsWorkingDay
                && ar.ReservationRightId !== Constants.ReservationsRecht.Visible,
            resRight: resRights,
            scheduleItems: [],
            additionalColumsData: [],

            // metadata
            isRessourceAvailable: ar.meta.isRessourceAvailable, // bookable with the necessary rights
            isBookingAllowed: ar.meta.isBookingAllowed, // user posseses the necessary rights
            actionLabel: ar.meta.actionLabel // text on reserve button 
        };

        ar.Occupancies.map(o => RoomScheduleComponent.createScheduleItems(o, text, minDate, maxDate))
            .forEach(x => x.forEach(y => item.scheduleItems.push(y)));

        return item;
    }
}
