export interface IReservationDateForm {
  id: number;
  date: FormControl;
  dateTimeFrom: FormControl;
  dateTimeTo: FormControl;
  message: FormControl;
}

export interface IReservationDateFormModel {
  id: number;
  date: string;
  dateTimeFrom: string;
  dateTimeTo: string;
  message: string;
}

export enum WarningImportanceLevel {
  none,
  statusLockedUntil,
  statusReservableUntil,
  statusOccupancyNotAllowed,
  noWorkday,
  NoReservationRight,
  searchDateInPast,
  timeSlotInPast,
  bookingConflicts
}

export interface IWarningInfo {
  warningType: WarningImportanceLevel,
  occupancyDate: Date,
  occupancyTimeFrom: Date,
  occupancyTimeTo: Date,
  dateForMessage?: Date,
  conflicts?: TimeSlot[]
}

@Component({
  selector: 'app-create-reservation-date',
  templateUrl: './create-reservation-date.component.html',
  styleUrls: ['./create-reservation-date.component.scss']
})

export class CreateReservationDateComponent implements OnInit, AfterContentInit, OnChanges, OnDestroy {

  constructor(
    private language: LanguageService,
    private roomPublicService: RoomPublicService,
    private devicePublicService: DevicePublicService,
    private translate: TranslateService
  ) { }

  // state props

  private get isNew(): boolean {
    if (!this.formId) {
      return true;
    }

    return !this.isSaved && (!this.formId);
  }

  get isReadonly(): boolean {
    return this.formGroup.get(nameof<IReservationDateForm>('date')).disabled;
  }

  // display props

  get displaySaveButton(): boolean {
    return !this.isNewReservation && !this.isNew;
  }

  get enableSaveButton(): boolean {
    return !this.isReadonly && this.formGroup.valid && (this.formGroup.dirty || this.isNew);
  }

  get displayCancelButton(): boolean {
    return !this.isReadonly && (this.formGroup.dirty || this.isNew);
  }

  get displayDeleteButton(): boolean {
    return !this.isNew;
  }

  get enableDeleteButton(): boolean {
    return !this.isReadonly;
  }

  // other props

  get formId(): number {
    return Number(this.formGroup.get(nameof<IReservationDateForm>('id')).value);
  }

  set formId(value: number) {
    this.formGroup.get(nameof<IReservationDateForm>('id')).patchValue(value);
  }

  get formDate(): Date {
    return DateHelper.parseIsoDateString(this.formGroup.get(nameof<IReservationDateForm>('date')).value);
  }

  set formDate(value: Date) {
    this.formGroup.get(nameof<IReservationDateForm>('date')).patchValue(value.toISOString());
  }

  get formFrom(): number {
    return Number(this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).value);
  }

  set formFrom(value: number) {
    this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).setValue(String(value));
  }

  get formTo(): number {
    return Number(this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).value);
  }

  set formTo(value: number) {
    this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).setValue(String(value));
  }

  get formMessage(): string {
    return this.formGroup.get(nameof<IReservationDateForm>('message')).value as string;
  }

  set formMessage(value: string) {
    this.formGroup.get(nameof<IReservationDateForm>('message')).setValue(value);
    this.timeSlotWarningUpdated.emit(Object.assign({}));
  }

  get hasError(): boolean
  {
    switch(this.detailedWarningInfo.warningType)
    {
      case WarningImportanceLevel.none:
        return false;
      default: 
        return true;
    }
  }

  public getCurrentReservationRight(): number{
    return this.currentReservationRight;
  }

  /**
   * contains the warning details, required for the more elaborate error infromation in the box, when only one date present
   */
  detailedWarningInfo :IWarningInfo = {warningType: WarningImportanceLevel.none, occupancyDate: null, occupancyTimeFrom: null, occupancyTimeTo: null};

  private currentReservationRight :number = Constants.ReservationsRecht.None;

  private setFormMessage(importanceLevel: WarningImportanceLevel, minutesStart: number, minutesEnd: number, dateForMessage?:Date, conflictingTimeSlots?: TimeSlot[], externalMessage?: string) : Promise<boolean>
  {
    console.log(`setFormMessage was called with ${importanceLevel}, ${minutesStart}, ${minutesEnd}, ${dateForMessage}, ${conflictingTimeSlots}, for date ${this.formDate.getDate()}.${this.formDate.getMonth()}`)
    return new Promise<boolean>((resolve) => {
      if(this.detailedWarningInfo.warningType == WarningImportanceLevel.none || importanceLevel <= this.detailedWarningInfo.warningType || this.formMessage == '')
      {
        this.detailedWarningInfo = {
          warningType:importanceLevel, 
          occupancyDate: this.currentTimeslotDate, 
          occupancyTimeFrom: DateHelper.setTimeFromMinutesOfDay(minutesStart, new Date(this.currentTimeslotDate)),
          occupancyTimeTo:  DateHelper.setTimeFromMinutesOfDay(minutesEnd, new Date(this.currentTimeslotDate)),
          dateForMessage: dateForMessage, 
          conflicts: conflictingTimeSlots}

        // get the text for the warning
        let messageName;
        switch(importanceLevel)
        {
          case WarningImportanceLevel.statusLockedUntil:
            messageName = 'RESSOURCE_STATE_CLOSED_UNTIL';
            break;
          case WarningImportanceLevel.statusReservableUntil:
            messageName = 'RESSOURCE_STATE_OPEN_UNTIL';
            break;
          case WarningImportanceLevel.statusOccupancyNotAllowed:
            messageName = 'RESSOURCE_STATE_CLOSED';
            break;
          case WarningImportanceLevel.noWorkday:
            messageName = 'RESSOURCE_STATE_NO_WORKDAY';
            break;
          case WarningImportanceLevel.NoReservationRight:
            messageName = 'RESSOURCE_NO_PERMISSION_OCCUPY';
            break;
          case WarningImportanceLevel.bookingConflicts:
            messageName = 'CONFLICTS';
            break;
          case WarningImportanceLevel.searchDateInPast:
            messageName = 'RESSOURCE_STATE_DATE_IN_PAST';
            break;
          case WarningImportanceLevel.timeSlotInPast:
            messageName = 'RESSOURCE_TIME_SLOT_IN_PAST';
            break;
          case WarningImportanceLevel.none:
            messageName = ''; // no message
            break;
        }

        if(messageName != '')
        {
          const sub = (dateForMessage ? this.translate.get(messageName, {resourceLabel:this.resourceLabelWithArticle,  date: this.language.formatDate(dateForMessage) }) : this.translate.get(messageName)).subscribe(
          (value: string) => {
            this.formMessage = value;
          });

          this.queueUnsubscribe(sub);

          if(conflictingTimeSlots != null && conflictingTimeSlots.length > 0)
          {
            // add them to the message
            let timeslotStrings : string[] = [];
            let message = this.formMessage;
            conflictingTimeSlots.forEach(slot => 
            {
              const conflict = this.translate.get('TIMESPAN_UNTIL', {startTime: DateHelper.getCHTimeString(slot.DateTimeFrom), endTime: DateHelper.getCHTimeString(slot.DateTimeTo)}).subscribe(
                (value2: string) => {
                  timeslotStrings.push(value2);
                }
              )
              this.queueUnsubscribe(conflict);
            })

            message = message + ": " + timeslotStrings.join(', ')
            this.formMessage = message;
          }
          resolve(true);
        }
        else if(externalMessage != '')
        {
          this.formMessage = externalMessage;
          resolve(true);
        }
        else {
          this.formMessage = '';
          resolve(true);
        }      
      }
      resolve(false); // no message set
    });
  }

  private clearFormMessage(warningType: WarningImportanceLevel)
  {
    if(this.detailedWarningInfo.warningType == warningType)
    {
      this.detailedWarningInfo.warningType = WarningImportanceLevel.none;
      this.formMessage = '';
    }
  }

  private setReservationRightInternal(newResRight:number)
  {
    if(newResRight != this.currentReservationRight)
    {
      this.currentReservationRight = newResRight;
      this.reservationRightChange.emit(Object.assign({}));
    }
  }

  subscriptions: Subscription[] = [];

  // todo tosc: handel invalid days (eg Sun. in room calendar)
  // todo tosc: allow delete only if has more than one saved date in form

  @Input() type: ResourceType;

  @Input() idRessource: number;

  @Input() hourMultiplicator = 4;

  @Input() hideLabels: boolean;

  @Input() hideButtons: boolean;

  /**
  * Angular Form model
  *
  * @type {FormGroup}
  * @memberof CreateReservationDateComponent
  */
  @Input() formGroup: FormGroup;

  /**
   * Index of element in FormArray
   *
   * @type {number}
   * @memberof CreateReservationDateComponent
   */
  @Input() index: number;

  /**
   * Indicate wheter the parent reservation is new or not
   *
   * @type {boolean}
   * @memberof CreateReservationDateComponent
   */
  @Input() isNewReservation: boolean;

  @Input() dataLoader: (startTime: Date, endTime: Date) => Promise<any> = null;

  @Input() supressErrorMessageNotice = false;

  @Input() statusInformation: IStatusInfo;

  @Input() reservationRight: ReservationRightOverTime;

  /**
   * internal unique string id across the whole application scope
   */
  uuid: string;

  /**
   * delete event
   *
   * @type {EventEmitter<number>}
   * @memberof CreateReservationDateComponent
   */
  @Output() delete: EventEmitter<number> = new EventEmitter<number>();

  /**
   * restore date event (undo changes)
   *
   * @type {EventEmitter<number>}
   * @memberof CreateReservationDateComponent
   */
  @Output() restore: EventEmitter<number> = new EventEmitter<number>();

  /**
   * save event
   *
   * @type {EventEmitter<number>}
   * @memberof CreateReservationDateComponent
   */
  @Output() save: EventEmitter<number> = new EventEmitter<number>();

  /**
   * Signals that the warning has changed, and that the parent should do an update
   */
  @Output() timeSlotWarningUpdated: EventEmitter<void> = new EventEmitter<void>();

    /**
   * Signals that the reservation right the user has for the time slot contained in this date object has changed, and that the dialog should therefore do an update
   */
  @Output() reservationRightChange: EventEmitter<void> = new EventEmitter<void>();

  /**
 * Vacancy and Occupancy minute TimeSlots according to Ressourcenkalender
 */
  @Input() resourceOccupancies: TimeSlot[];

  dateFormat: string;

  /**
   * Available TimeSlots according to Ressourcenkalender
   *
   * @type {TimeSlot[]}
   * @memberof CreateReservationDialogComponent
   */
  timeSlots: TimeSlot[];

  /**
   * Time from dropdown selectables
   *
   * @type {IMultiDropdownData[]}
   * @memberof CreateReservationDateComponent
   */
  selectTimeFromValues: IMultiDropdownData[] = [];

  /**
   * Time to dropdown selectables
   *
   * @type {IMultiDropdownData[]}
   * @memberof CreateReservationDateComponent
   */
  selectTimeToValues: IMultiDropdownData[] = [];

  currentTimeslotDate: Date;

  isSaved: boolean;

  isWorking: boolean;

  resourceLabelWithArticle: string;

  // services
  resourcePublicService: IResourcePublicService;

  /**
  * Create a new formGroup model
  *
  * @static
  * @returns {IReservationDateForm}
  * @memberof CreateReservationDateComponent
  */
  public static createFormGroupModel(formBuilder: FormBuilder): FormGroup {
    const model: IReservationDateForm = {
      id: 0,
      date: new FormControl('', [
        Validators.required
      ]),
      dateTimeFrom: new FormControl('', [
        Validators.required
      ]),
      dateTimeTo: new FormControl('', [
        Validators.required
      ]),
      message: new FormControl(''),
    };
    const fg = formBuilder.group(model as any);
    
    return fg;
  }

  ngOnChanges(changes: SimpleChanges) {
    if ('resourceOccupancies' in changes || 'timeSlots' in changes) {
        this.validateTimeSlot()
    }
  }

  ngOnInit() {
    if (this.isNewReservation === undefined) {
      throw Error(nameof<CreateReservationDateComponent>('isNewReservation') + ' must be set on CreateReservationDateComponent');
    }

    // get a unique id
    this.uuid = id4();

    this.loadResourceOccupancies();

    this.language.getDateFormat().then((val) => {
      this.dateFormat = val;
    });

    switch (this.type) {
      case ResourceType.Raum:
        this.resourcePublicService = this.roomPublicService;
        this.translate.get('THE_ROOM').subscribe(value => {
            this.resourceLabelWithArticle = value;
        });
        break;
      case ResourceType.Gerät:
        this.resourcePublicService = this.devicePublicService;
            this.translate.get('THE_DEVICE').subscribe(value => {
            this.resourceLabelWithArticle = value;
        });
        break;
      default:
        throw Error(nameof<CreateReservationDateComponent>('type') + ' must be set on CreateReservationDateComponent');
    }
  }

  ngAfterContentInit(): void {
    this.initForm();
  }

  private loadResourceOccupancies()
  {
    if (typeof this.dataLoader === 'function') {
      const formDateTimestamp = this.formDate.getTime();
      const from = new Date(formDateTimestamp + this.formFrom);
      const to = new Date(formDateTimestamp + this.formTo);

      this.dataLoader(from, to).then(data => {
        this.resourceOccupancies = data;
      })
        .then(() => {
          this.validateTimeSlot();
        })
        .catch(er => {
          console.error('Failed to load resource occupancies', er);
        });

    } else if (this.dataLoader) {
      throw new Error('Invalid data loader specified');
    }
  }

  private loadTimeSlots(date: Date): Promise<any> {

    if (this.idRessource === 0 || !(date instanceof Date)) {
      return;
    }

    this.currentTimeslotDate = date;

    return this.resourcePublicService.getTimeSlots(
      this.idRessource,
      DateHelper.getUnixTime(new Date(date.getFullYear(), date.getMonth(), date.getDate())),
      DateHelper.getUnixTime(new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59, 999))
    ).pipe(
      tap(x => {
        this.timeSlots = (x as TimeSlot[]).map(o => TimeSlot.create(o)).sortByProp(r => r.StartMinuteIndex);
        this.selectTimeFromValues = this.getFromDropdownData(this.timeSlots);
        if (!this.formFrom) {
          this.formFrom = Number(this.selectTimeFromValues[0].key);
        }
        this.validateTimeSlot();
      }),
      catchError((err: HttpErrorResponse) => {
        this.currentTimeslotDate = null;
        return throwError(err);
      })
    ).toPromise();
  }

  ngOnDestroy() {
    this.setFormMessage(WarningImportanceLevel.none, null, null);
    this.timeSlotWarningUpdated.emit(Object.assign({}));
    this.reservationRightChange.emit(Object.assign({}));
    this.subscriptions.forEach(s => s.unsubscribe());
  }

  /**
   * Set enabled/disbled state and error message for timeslots
   *
   * @private
   * @memberof CreateReservationDateComponent
   */
  private validateTimeSlot() {
    if(!this.resourceOccupancies || !this.timeSlots)
    {
      return;
    }
    
    if(this.checkDateValid())
    {
      this.checkTimeSlotValid();
    }
  }

  private checkDateValid(): boolean {
    let dateValid = true;
    
    if(this.isDatePast(this.formDate))  // date in the past? We are in the date component here, which is used in the reservation dialog -> do the easiest check first
    {
      this.setFormMessage(WarningImportanceLevel.searchDateInPast, null, null, this.formDate)
      .then(() =>
      {
        this.disableTimeDropdowns(true);
        dateValid = false;
      });
    }
    else {
      let statusWarningLevel = this.getStatusWarning(this.statusInformation, this.formDate);
      if(statusWarningLevel == WarningImportanceLevel.statusLockedUntil || statusWarningLevel == WarningImportanceLevel.statusReservableUntil)
      {
        this.setFormMessage(statusWarningLevel, null, null, this.statusInformation.StatusDate)
        .then(() =>
        {
          this.disableTimeDropdowns(true);
          dateValid = false;
        });
      }
      else if(statusWarningLevel == WarningImportanceLevel.statusOccupancyNotAllowed)
      {
        this.setFormMessage(statusWarningLevel, null, null)
        .then(() =>
        {
          this.disableTimeDropdowns(true);
          dateValid = false;
        });
      } 
      else if(this.timeSlots.length === 0)  // check if the room is closed
      {  
        this.setFormMessage(WarningImportanceLevel.noWorkday, null, null, this.formDate)
        .then(() =>
        {
          this.disableTimeDropdowns(true);
          dateValid = false;
        });
      }
    }
    
    this.formGroup.updateValueAndValidity({emitEvent: false});
    this.disableTimeDropdowns(!dateValid);
    return dateValid;
  }

  private disableTimeDropdowns(disableTimeDropdowns:boolean)
  {
    if (disableTimeDropdowns) {
      this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).disable();
      this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).disable();
    } else {
      this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).enable();
      this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).enable();
    }
  }
  
  private getStatusWarning(statusInfo: IStatusInfo, searchDate:Date) : WarningImportanceLevel
  {
    let tempSearchDate = new Date(searchDate);

    if(statusInfo == null)
    {
      console.warn(`No status info (yet). Called for search date ${searchDate}`);
      return;
    }

    // status
    switch (statusInfo.StatusId) {
      case StatusId.rrGesperrt:
        return WarningImportanceLevel.statusOccupancyNotAllowed;
      case StatusId.rrGesperrtBis:
        if (statusInfo.StatusDate > searchDate) {
          return WarningImportanceLevel.statusLockedUntil; 
        }
        break;
      case StatusId.rrReservierbarBis:
        if (new Date(tempSearchDate.setHours(0,0,0,0)) > new Date(statusInfo.StatusDate)) {
          return WarningImportanceLevel.statusReservableUntil;
        }
        break;
      case StatusId.rrReservierbar: // ok
        return WarningImportanceLevel.none;
      default:
        console.warn(`status unknown: (${statusInfo.StatusId} - ${statusInfo.Status})`);
        break;
    }
  }

  private isDatePast(searchDate:Date): boolean
  {
    return searchDate.setHours(0,0,0,0) < new Date().setHours(0,0,0,0)
  }

  private checkTimeSlotValid(){
    // check if it's in the past
    // then check reservation right
    // then check for conflicts 
    // return if any error found
    const $this = this;
    const currentStartMinuteCount = Number($this.formGroup.value.dateTimeFrom);
    const currentEndMinuteCount = Number($this.formGroup.value.dateTimeTo)

    if(!this.checkTimeSlotNotInPast(currentStartMinuteCount, currentEndMinuteCount))  // it is in the past
    {
      return;
    }

    let resRight = this.checkTimeSlotReservationRight(currentStartMinuteCount, currentEndMinuteCount);
    if(resRight != Constants.ReservationsRecht.None && resRight != Constants.ReservationsRecht.Visible)
    {
      this.checkTimeSlotForConflicts(currentStartMinuteCount, currentEndMinuteCount);
    }
  }

  private checkTimeSlotReservationRight(startTimeMinutes: number, endTimeMinutes: number) : number
  {
    let tsDate = new Date(this.formGroup.getRawValue().date).setHours(0,0,0,0);
    let minutesDiff:number = (tsDate - Date.now())/(1000*60);
    let startTimeMinutesFromNow: number = Number(startTimeMinutes) + minutesDiff;
    let endTimeMinutesFromNow: number = Number(endTimeMinutes) + minutesDiff;

    let resRight = Constants.ReservationsRecht.None;

    if(this.reservationRight)
    {
      resRight = this.reservationRight.getReservationRightForTimeSlot(startTimeMinutesFromNow, endTimeMinutesFromNow);

      if(resRight == Constants.ReservationsRecht.None || resRight == Constants.ReservationsRecht.Visible)
      {
        this.setFormMessage(WarningImportanceLevel.NoReservationRight, startTimeMinutes, endTimeMinutes);
      }
      else{
        this.clearFormMessage(WarningImportanceLevel.NoReservationRight);
      }
    }
    
    this.setReservationRightInternal(resRight);
    return resRight;
  }

  private checkTimeSlotNotInPast(startTimeMinutes: number, endTimeMinutes: number) :boolean
  {
    if(new Date(this.currentTimeslotDate).setHours(0,0,0,0) == new Date().setHours(0,0,0,0) 
      && (new Date().getMinutes() + new Date().getHours()*60) > endTimeMinutes)
    {
      // time slot in the past
      this.setFormMessage(WarningImportanceLevel.timeSlotInPast, startTimeMinutes, endTimeMinutes, null)
      return false;
    }

    this.clearFormMessage(WarningImportanceLevel.timeSlotInPast);
    return true;
  }

  queueUnsubscribe(sub: Subscription) {
    if (this.subscriptions.includes(sub)) { return; }

    // ? maybe use a set here
    this.subscriptions.push(sub);
  }

  setOrClearConflictMessage(shouldPresent: boolean, conflictingSlots?: TimeSlot[], minutesStart?: number, minutesEnd?: number): void {
    if (shouldPresent === true) {
      this.setFormMessage(WarningImportanceLevel.bookingConflicts, minutesStart, minutesEnd, null, conflictingSlots)
    } else {
      // clear conflict message this.setFormMessage(WarningImportanceLevel.none);
      this.clearFormMessage(WarningImportanceLevel.bookingConflicts);
    }
  }

  /**
   * handle save click
   *
   * @memberof CreateReservationDateComponent
   */
  onSaveClick() {
    if (!this.isReadonly && this.enableSaveButton) {
      this.save.emit(this.index);
    }
  }

  /**
   * handle delete click
   *
   * @memberof CreateReservationDateComponent
   */
  onDeleteClick() {
    if (!this.isReadonly) {
      this.delete.emit(this.index);
    }
  }

  /**
   * remove unsafed item
   *
   * @memberof CreateReservationDateComponent
   */
  onCancelClick() {
    if (!this.isReadonly) {
      if (this.isNew) {
        this.delete.emit(this.index);
      } else {
        this.restore.emit(this.index);
      }
    }
  }

  /**
   * Initialize the form
   *
   * @private
   * @memberof CreateReservationDateComponent
   */
  private initForm() {
    // preset values
    const date = this.formDate;
    if (date !== undefined && date instanceof Date) {
      const startMinutes = this.formFrom;

      this.loadTimeSlots(date)
        .then(_ => {
          this.updateToDropdownData(Number(startMinutes));
          this.attachFormEvents();
        })
        .catch(_ =>
        {
          this.attachFormEvents();
        });
    } else {
      this.attachFormEvents();
    }
  }

  onDateChange(newValue: string) {
    const date = DateHelper.parseIsoDateString(newValue);
    if (!this.currentTimeslotDate || date.toDateString() !== this.currentTimeslotDate.toDateString()) {
      this.setFormMessage(WarningImportanceLevel.none, null, null);
      this.loadTimeSlots(date);
      this.loadResourceOccupancies();
    }
  }

  groupByContinuosBlocks(blocks: TimeSlot[]): TimeSlot[][] {
    const groups = blocks.reduce((grps: TimeSlot[][], block: TimeSlot, i: number, all: TimeSlot[]) => {
      if (grps === null) { return [[block]]; }

      const last = grps.pop();
      grps.push(last);
      const lastTimeSlot = last.slice(-1)[0];

      if (lastTimeSlot.EndMinuteIndex + 1 === block.StartMinuteIndex) {
        last.push(block);
      } else {
        grps.push([block]);
      }

      return grps;

    }, null);

    return groups;
  }

  onStartTimeChange(startMinutes: string) {
    const $this = this;
    const newStartMinuteCount = Number(startMinutes);
    const currentStartMinuteCount = Number($this.formGroup.value.dateTimeFrom);

    if (startMinutes !== '' && !this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).disabled) {
      this.updateToDropdownData(Number(startMinutes));
    }

    if (newStartMinuteCount == currentStartMinuteCount || this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).disabled) return;

    const currentEndMinuteCount = Number($this.formGroup.value.dateTimeTo);

    let resRight = this.checkTimeSlotReservationRight(newStartMinuteCount, currentEndMinuteCount);
    if(resRight != Constants.ReservationsRecht.None && resRight != Constants.ReservationsRecht.Visible)
    {
      this.checkTimeSlotForConflicts(newStartMinuteCount, currentEndMinuteCount);
    }
  }

  onEndTimeChange(endMinuteIndex: string) {
    const $this = this;
    const newEndMinuteIndex = Number(endMinuteIndex) - 1;
    const currentStartMinuteIndex = Number($this.formGroup.value.dateTimeFrom);
    const currentEndMinuteCount = Number($this.formGroup.value.dateTimeTo);

    if (Number(endMinuteIndex) == currentEndMinuteCount || this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).disabled) return;

    if(!this.checkTimeSlotNotInPast(currentStartMinuteIndex, newEndMinuteIndex))
      return;

    let resRight = this.checkTimeSlotReservationRight(currentStartMinuteIndex, newEndMinuteIndex);
    if(resRight != Constants.ReservationsRecht.None && resRight != Constants.ReservationsRecht.Visible)
    {
      this.checkTimeSlotForConflicts(currentStartMinuteIndex, newEndMinuteIndex);
    }
  }

  private checkTimeSlotForConflicts(startMinuteIndex: number, endMinuteIndex: number)
  {
    const $this = this;

    let withinFreeSlot = -1 !== $this.resourceOccupancies.findIndex(
      ts => ts.SlotType === TimeSlotType.Vacant
        && ts.StartMinuteIndex <= startMinuteIndex
        && ts.EndMinuteIndex >= endMinuteIndex - 1
    );

    // this logic is for handling conflict error for existing reservations
    if (withinFreeSlot !== true && this.formId && $this.resourceOccupancies.findIndex(roc => Number(roc.IdObject) === this.formId) !== -1) {
      const selTS = $this.resourceOccupancies.filter(roc => roc.SlotType === TimeSlotType.Vacant || Number(roc.IdObject) === this.formId);
      const conblocks = this.groupByContinuosBlocks(selTS);

      withinFreeSlot = -1 !== conblocks.findIndex(
        tsb => tsb[0].StartMinuteIndex <= startMinuteIndex
          && tsb.slice(-1)[0].EndMinuteIndex >= endMinuteIndex - 1
      );
    }

    if (withinFreeSlot === false) {
      const timeSlotBlocks = $this.resourceOccupancies.filter(ts => ts.SlotType !== TimeSlotType.Vacant
        && ts.EndMinuteIndex > startMinuteIndex
        && ts.StartMinuteIndex < endMinuteIndex);

      const blockedSlots = timeSlotBlocks.filter(ts => ts.SlotType !== TimeSlotType.Vacant);
      const firstSlot = blockedSlots[0];
      const lastSlot = blockedSlots[blockedSlots.length - 1];

      if(blockedSlots.length > 0)
      {
        $this.setOrClearConflictMessage(true, blockedSlots, startMinuteIndex, endMinuteIndex);
      }
    } else {
      // clear validation notice
      $this.setOrClearConflictMessage(false);
    }
  }

  /**
   * attach listening for form-changes
   *
   * @private
   * @memberof CreateReservationDateComponent
   */
  private attachFormEvents() {
    if (this.formGroup.disabled) { return; }

    const sub = this.formGroup.get(nameof<IReservationDateForm>('date')).valueChanges.subscribe((value: string) => {
      this.onDateChange(value);
    });
    this.queueUnsubscribe(sub);

    const sub2 = this.formGroup.get(nameof<IReservationDateForm>('dateTimeFrom')).valueChanges.subscribe((startMinutesIndex: string) => {
      this.onStartTimeChange(startMinutesIndex);
    });
    this.queueUnsubscribe(sub2);

    const sub3 = this.formGroup.get(nameof<IReservationDateForm>('dateTimeTo')).valueChanges.subscribe((endMinuteIndex: string) => {
      this.onEndTimeChange(endMinuteIndex);
    });
    this.queueUnsubscribe(sub3);
  }

  /**
   * Get 'from' dropdown values
   *
   * @private
   * @param {TimeSlot[]} timeSlots
   * @returns {IMultiDropdownData[]}
   * @memberof CreateReservationDialogComponent
   */
  private getFromDropdownData(timeSlots: TimeSlot[]): IMultiDropdownData[] {
    const multiplicator = this.hourMultiplicator;

    const increment = 60 / multiplicator;
    const result = new Array<IMultiDropdownData>();

    timeSlots.forEach(ts => {
      const startMinutes = DateHelper.getMinutesOfDay(ts.DateTimeFrom);
      const endMinutes = DateHelper.getMinutesOfDay(ts.DateTimeTo);

      // start on room open, even if time is not within interval (eg. 6:55 is not in 15 min interval)
      const alignedStart = (startMinutes % 60) % increment === 0
        ? startMinutes
        : Math.ceil(startMinutes / 60 * multiplicator) / multiplicator * 60;
      if (startMinutes !== alignedStart) {
        result.push({ key: String(startMinutes), text: StringHelper.formatTimeMinutes(startMinutes), selected: false });
      }

      for (let i = alignedStart; i < endMinutes; i += increment) {
        result.push({ key: String(i), text: StringHelper.formatTimeMinutes(i), selected: false });
      }
    });

    return result;
  }

  /**
   * Update 'to' dropdown values
   *
   * @private
   * @param {number} startMinutes
   * @memberof CreateReservationDialogComponent
   */
  private updateToDropdownData(startMinutes: number) {
    // preserve initial/previous timespan
    const oldStart = Number(this.formGroup.value.dateTimeFrom);
    const diff = Number(this.formGroup.value.dateTimeTo) - oldStart;
    const endPreset = diff > 0 ? startMinutes + diff : startMinutes + 60;

    const selectedSlot = this.timeSlots
      .find(ts => ts.StartMinuteIndex <= startMinutes && ts.EndMinuteIndex > startMinutes);

    const endMinutes = selectedSlot === undefined
      ? (Array.isArray(this.resourceOccupancies) && this.resourceOccupancies.length > 0
        ? this.resourceOccupancies.reverse().find(oc => oc && oc.SlotType !== TimeSlotType.Vacant).StartMinuteIndex - 1
        : 0)
      : selectedSlot.EndMinuteIndex;

    const result = new Array<IMultiDropdownData>();
    if (selectedSlot !== undefined) {

      const increment = 60 / this.hourMultiplicator;
      for (let i = startMinutes + increment; i < endMinutes; i += increment) {
        result.push({ key: String(i), text: StringHelper.formatTimeMinutes(i), selected: i === endPreset });
      }

      result.push({ key: String(endMinutes), text: StringHelper.formatTimeMinutes(endMinutes), selected: endMinutes === endPreset });
    }

    this.selectTimeToValues = result;

    const selectedItems = this.selectTimeToValues.filter(x => x.selected);
    if (ArrayHelper.hasAny(selectedItems) && Number(selectedItems[0].key) !== this.formTo) {
      this.formTo = Number(selectedItems[0].key);
    } else if (endPreset > this.formTo) {
      // TODO: clear up if time should be rounded to 5min and when timespan exceeds last possible time choice
      // does not match any dropdown entry, but set directly since free input is allowed
      // limit to last minute index of current day
      this.formTo = Math.min(endPreset, 24 * 60 - 1);
    }
  }

  // wrapper for service class caller
  protected getCHTimeString(time: Date): string {
    return DateHelper.getCHTimeString(time);
  }
}
