import { Component, OnInit, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { OccupancyType } from 'src/app/shared/models/occupancy';
import { TimeSlot } from 'src/app/shared/models/time-slot.model';
import { StringHelper } from 'src/app/shared/utils/string-helper';
import { ColorHelper } from 'src/app/shared/utils/color-helper';
import { Observable } from 'rxjs';
import { DateHelper } from 'src/app/shared/utils/date-helper';
import { ICreateReservationParams } from '../create-reservation-dialog/create-reservation-dialog-base.component';
import { Constants } from 'src/app/shared/models/constants.model';
import { ReservationRightOverTime } from 'src/app/shared/models/reservation-right-time-range';
import { TranslateService } from '@ngx-translate/core';
import { IStatusInfo } from '../room-allocation-table/room-allocation-table.component';
import { RoomService } from 'src/app/shared/services/rest/room.service';

@Component({
  selector: 'app-room-schedule-item',
  templateUrl: './room-schedule-item.component.html',
  styleUrls: ['./room-schedule-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RoomScheduleItemComponent implements OnInit {

  @Input() scheduleItem: ScheduleItem;

  /**
   * Start hour of the table
   *
   * @memberof RoomScheduleComponent
   */
  @Input() fromHour: number;

  /**
   * End hour of the table
   *
   * @memberof RoomScheduleComponent
   */
  @Input() toHour: number;

  /**
   * Event raised on click on "create new"
   *
   * @memberof RoomScheduleItemComponent
   */
  @Output() createReservation = new EventEmitter<ICreateReservationParams>();

  constructor() { }

  ngOnInit() {
    if (this.fromHour === undefined) {
      throw new Error('Please provide property ' + nameof<RoomScheduleItemComponent>('fromHour'));
    }
    if (this.toHour === undefined) {
      throw new Error('Please provide property ' + nameof<RoomScheduleItemComponent>('toHour'));
    }
  }

  /**
   * Calculates the space relative to the top of the container
   *
   * @param {ScheduleItem} item
   * @returns {string}
   * @memberof RoomScheduleComponent
   */
  getPanelTop(): string {
    const span = this.scheduleItem.from.getMinutes();
    return String(span / 60 * 100) + '%';
  }

  /**
   * Calculates the relative height of the panel
   *
   * @param {ScheduleItem} item
   * @returns {string}
   * @memberof RoomScheduleComponent
   */
  getPanelHeight(): string {
    // adjust start time
    const start = new Date(this.scheduleItem.from);
    if (start.getHours() < this.fromHour) {
      start.setHours(this.fromHour);
      start.setMinutes(0);
    }

    // adjust end time
    const end = new Date(this.scheduleItem.to);
    if (end.getHours() >= this.toHour + 1) {
      end.setHours(this.toHour + 1);
      end.setMinutes(0);
    }

    if ((end.getTime() - start.getTime()) < 5 * 60 * 1000) { // 5 min margin
      return '0';
    }

    // calculate height
    const span = Math.floor((end.getTime() - start.getTime()) / 1000);
    return String(span / 3600 * 2) + 'rem';
  }

  /**
   * Helper to format time-span of the occupancy
   *
   * @param {Occupancy} occ
   * @returns {string}
   * @memberof RoomScheduleComponent
   */
  formatTimeSpan(occ: ScheduleItem): string {
    if (occ === undefined) {
      throw new Error('occ undefined');
    }

    return StringHelper.formatTimeSpan(
      occ.from.getHours(),
      occ.from.getMinutes(),
      occ.to.getHours(),
      occ.to.getMinutes()
    );
  }

  /**
   * raise createReservation-event
   *
   * @param {ScheduleItem} scheduleItem
   * @memberof RoomScheduleItemComponent
   */
  onClickCreateReservation(scheduleItem: ScheduleItem): void {
    this.createReservation.emit({
      idReservation: null,
      idRessource: scheduleItem.idRessource,
      from: new Date(scheduleItem.from),
      to: new Date(scheduleItem.to),
      statusInfo: scheduleItem.statusInfo,
      reservationRight: scheduleItem.reservationRight
    });
  }

}

/**
 * Panels displayed in table-cells (day wise)
 * Note: one Occupany might be many ScheduleItem
 *
 * @class ScheduleItem
 */
export class ScheduleItem {

  idRessource: number;

  from: Date;

  to: Date;

  designation: string;

  description: string;

  color: string;

  textColor: string;

  occupancyType: OccupancyType;

  statusInfo: IStatusInfo;

  reservationRight: ReservationRightOverTime;

  reservationRightId: number;

  isBookable: boolean;

  constructor(idRessource: number, from: Date, to: Date, text: string,
    description: string, defaultText: Observable<any>, color: string, statusInfo:IStatusInfo, resRight: ReservationRightOverTime, reservationRightId:number, occupanyType: OccupancyType) {
    this.idRessource = idRessource;
    this.description = description;
    this.from = from;
    this.to = to;
    // replace color white with defined darker gray color
    this.color = !StringHelper.hasAny(color) ||
        ['white', '#ffffff'].includes(color) ||
        `${color}`.replace(/\s+/g, '').includes('(255,255,255)')
      ? '#dbdbdb'
      : color;

    this.statusInfo = statusInfo;
    this.reservationRight = resRight;
    this.reservationRightId = reservationRightId;
    this.occupancyType = occupanyType;
    this.isBookable = occupanyType === OccupancyType.Reservable;

    if (StringHelper.hasAny(text)) {
      this.designation = text;
    } else {
      defaultText.subscribe(x => this.designation = x);
    }

    this.setTextColor();
  }

  /**
   * Merge overlapping elements in scheduleItem array
   */
  public static cleanUpSchedulteItems(items: Array<ScheduleItem>) : Array<ScheduleItem>{
    // merge overlapping elements into one
    const workingElements = new Array<ScheduleItem>();
    items.sortByProp(x => x.from).forEach(element => {
      const i = workingElements.findIndex((si) => si.IntersectsExclude(element));
      if (i !== -1) {
        // expand the found element to the combined range
        workingElements[i].from = DateHelper.Min(workingElements[i].from, element.from);
        workingElements[i].to = DateHelper.Max(workingElements[i].to, element.to);
      } else {
        workingElements.push(element);
      }
    });

    return items;
  }
  /**
   * Create empty elements to click to reserve
   *
   * @static
   * @param {Array<ScheduleItem>} items
   * @returns {Array<ScheduleItem>}
   * @memberof ScheduleItem
   */
  public static createEmptyScheduleItems(
    idRessource: number,
    items: Array<ScheduleItem>,
    startDate: Date,
    endDate: Date,
    resRightOverTime: ReservationRightOverTime,
    roomStatusInfo: IStatusInfo,
    roomService: RoomService,
    translate: TranslateService
  ): Array<ScheduleItem> {
    const workingElements0 = this.cleanUpSchedulteItems(items);
    const resRightChanges = resRightOverTime.getDateTimesRightChanges();

    // 10 minutes
    const margin = 10 * 60 * 1000;

    const gaps = new Array<ScheduleItem>();
    let lastEnd: Date = null;
    let nextOccupancyStart: Date = null;

    let workingElements = workingElements0.sortByProp(x => x.from);

    // loop to find gaps
    workingElements.sortByProp(x => x.from).forEach(workingElement => {
      if (lastEnd === null) {
        lastEnd = startDate;
      }

      nextOccupancyStart = workingElement.from;

      this.checkStatusHandleResRightChangesAddGaps(lastEnd, nextOccupancyStart, margin, resRightChanges, roomStatusInfo, roomService, gaps, resRightOverTime, translate, idRessource);

      lastEnd = new Date(workingElement.to.getTime() + 1); // eg. adjust 5:59:59.999 to 6:00:00.000
      
    });

    if (lastEnd === null) {
      // no occupancies
      // TODO MSCH, split at reservation right changes?
      // this is the case that there are no occupancies between start and end date at all - if start and end date are not on the same day, call 'checkStatusHandleResRightChangesAddGaps' for each day seperately
      let startDateHour0 = new Date(startDate).setHours(0,0,0,0);
      let endDateHour0 = new Date(endDate).setHours(0,0,0,0);
      if(startDateHour0 == endDateHour0)
      {
        this.checkStatusHandleResRightChangesAddGaps(startDate, endDate, margin, resRightChanges, roomStatusInfo, roomService, gaps, resRightOverTime, translate, idRessource)
      }
      else 
      {
        // how many days? 
        let msInDay = 1000*60*60*24;
        let numberOfDays = Math.round((endDateHour0 - startDateHour0) / msInDay);
        for (let i = 0; i < numberOfDays; i++)
        {
          let tempStartDate = new Date(startDate.getUTCDate() + i*msInDay);
          let tempEndDate = new Date(Math.min((startDate.getUTCDate() + (i+1)*msInDay), endDate.getUTCDate()));
          
          this.checkStatusHandleResRightChangesAddGaps(tempStartDate, tempEndDate, margin, resRightChanges, roomStatusInfo, roomService, gaps, resRightOverTime, translate, idRessource)
        }
      }
    } else if ((endDate.getTime() - margin) > lastEnd.getTime()) {
      // add last item
      gaps.push(ScheduleItem.createClickableWithReservationRight(lastEnd, endDate, roomStatusInfo, resRightOverTime, translate, idRessource));
    }

    return gaps;
  }

  private static checkStatusHandleResRightChangesAddGaps(gapStart: Date, gapEnd: Date, margin: number, resRightChanges: Date[], roomStatusInfo: IStatusInfo, roomService: RoomService, gaps: Array<ScheduleItem>, resRightOverTime:ReservationRightOverTime, translate: TranslateService, idRessource:number)
  {
    let elementHandled = false;

    // status allows reservation? 
    if(roomStatusInfo != null && roomService != null)
    {
      const observer = roomService.getStatusWarning(roomStatusInfo, gapStart);
      if (observer != null) {

        gaps.push(ScheduleItem.createClickableWithStatusInfo(gapStart, gapEnd, observer, idRessource));

        elementHandled = true;
      };
    }

    if(!elementHandled)
    {
      // reservationRightChange?
      let lastEnd = gapStart;

      if(resRightChanges != null && resRightChanges.length > 0){
        resRightChanges.forEach(rightChange => { 
          if(rightChange >= gapStart && rightChange < gapEnd)
          {
            // insert a schedulte item, and move lastEnd
            const dateDiff = gapEnd.getTime() - lastEnd.getTime();
            if (dateDiff > margin) {
              gaps.push(ScheduleItem.createClickableWithReservationRight(lastEnd, rightChange, roomStatusInfo, resRightOverTime, translate, idRessource));
            }
            lastEnd = rightChange;
          }
        });
      }

      const dateDiff = gapEnd.getTime() - lastEnd.getTime();
      if (dateDiff > margin) {
        gaps.push(ScheduleItem.createClickableWithReservationRight(lastEnd, gapEnd, roomStatusInfo, resRightOverTime, translate, idRessource));
      }
    }
  }

  public static createClickableWithReservationRight(startTime:Date, endTime:Date, statusInfo:IStatusInfo, resRightOverTime:ReservationRightOverTime, translate:TranslateService, resourceId:number): ScheduleItem {
    let occupancyType: OccupancyType, text: string, desc:string;
    desc = 'desc';
    let reservationRightId = resRightOverTime.getReservationRightForTimeSlotDates(startTime, endTime);

    if(reservationRightId != null && reservationRightId != undefined && (
      reservationRightId === Constants.ReservationsRecht.Reservable ||
      reservationRightId === Constants.ReservationsRecht.ProvReservable ||
      reservationRightId === Constants.ReservationsRecht.Requestable))
    {
      occupancyType = OccupancyType.Reservable;
    }
    else{
      occupancyType = OccupancyType.Unavailable;
    }

    let scheduleItem = new ScheduleItem(
      resourceId,
      startTime,
      endTime,
      null,
      desc,
      this.getClickableTextWithRight(reservationRightId, translate),
      '##00FF00',
      statusInfo,
      resRightOverTime,
      reservationRightId,
      occupancyType
    )

    return scheduleItem;
  }

  public static createClickableWithStatusInfo(startTime:Date, endTime:Date, displayText:Observable<string>, resourceId:number): ScheduleItem {
    let occupancyType: OccupancyType, desc:string, reservationRightId: number; 
    desc = 'desc';
    occupancyType = OccupancyType.Unavailable;
    reservationRightId = Constants.ReservationsRecht.None;

    let scheduleItem = new ScheduleItem(
      resourceId,
      startTime,
      endTime,
      null,
      desc,
      displayText,
      '##00FF00',
      null,
      null,
      reservationRightId,
      occupancyType
    )

    return scheduleItem;
  }

  private static getClickableTextWithRight(reservationRightId: number, translate:TranslateService):Observable<string>
  {
    switch(reservationRightId)
    {
      case Constants.ReservationsRecht.Reservable:
      case Constants.ReservationsRecht.ProvReservable:
        return translate.get('CLICK_TO_RESERVE');
      case Constants.ReservationsRecht.Requestable:
        return translate.get('CLICK_TO_REQUEST');
      case  Constants.ReservationsRecht.Visible:
        return translate.get('NOT_BOOKABLE');
    }

    return translate.get('NOT_BOOKABLE');
  }

  private setTextColor() {
    const lightText = '#f8f9fa'; // todo tosc
    const darkText = '#343a40'; // todo tosc
    this.textColor = ColorHelper.colorDifference(this.color, lightText) > ColorHelper.colorDifference(this.color, darkText)
      ? lightText : darkText;
  }

  /**
   * returns true if range @param {other} intersects this range, <b>excluding</b> the exact timestamp (false if the ranges touch)
   *
   * @param {ScheduleItem} other
   * @returns {boolean}
   * @memberof ScheduleItem
   */
  public IntersectsExclude(other: ScheduleItem): boolean {
    if (other.to <= this.from || other.from >= this.to || this.to <= other.from || this.from >= other.to) {
      return false;
    }
    return true;
  }

}
