import { Injectable, Inject, Renderer2 } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DOCUMENT } from '@angular/platform-browser';
import * as moment from 'moment';
import { StorageService } from './storage.service';
import { ArrayHelper } from '../utils/array-helper';

@Injectable({
  providedIn: 'root'
})
export class LanguageService {

  /**
   * Currently selected UiLanguage
   *
   * @type {string}
   * @memberof LanguageService
   */
  currentLanguage: string;
  dateSeparator: string;
  dateFormatArray: string[];
  dateFormat: string;
  currentDateFormat: any;

  constructor(
    private translate: TranslateService,
    private storage: StorageService,
    @Inject(DOCUMENT) private doc: Document
  ) { }

  /**
   * Returns the best machting language from the given set of languages
   * according to the users browser settings
   *
   * @static
   * @param {string[]} availableLanguages
   * @returns {string}
   * @memberof LanguageHelpers
   */
  static GetBestClientLanguage(availableLanguages: string[]): string {
    const preferredLanguages = this.GetNavigatorLanguages();

    // no preferences
    if (preferredLanguages === null) {
      return null;
    }

    for (let i = 0; i < preferredLanguages.length; i++) {
      const lang = preferredLanguages[i].toLowerCase();

      // find available locales for given language
      const locales = availableLanguages.filter(l => {
        return l.substr(0, 2).toLowerCase() === lang.substr(0, 2);
      });

      // next if no match
      if (ArrayHelper.isNullOrEmpty(locales)) {
        continue;
      }

      // try to find exact locale
      const exactMatches = locales.filter(l => l.toLowerCase() === lang);
      if (ArrayHelper.hasAny(exactMatches)) {
        return exactMatches[0];
      }

      // return first locale that matches language (fallback)
      return locales[0];
    }

    return null;
  }

  /**
   * Returns a list of browser prefered laguages
   *
   * @private
   * @static
   * @returns {(ReadonlyArray<string> | null)}
   * @memberof LanguageService
   */
  private static GetNavigatorLanguages(): ReadonlyArray<string> | null {
    let langs = window.navigator.languages;
    if (langs === undefined) {
      const ieLang = (<any>window.navigator).userLanguage;
      if (ieLang !== undefined) {
        // ie...
        langs = [(<any>window.navigator).userLanguage];
      } else {
        return null;
      }
    }
    return langs;
  }

  /**
   * Get the currently selected uiLanguage
   *
   * @returns
   * @memberof LanguageService
   */
  getLanguage() {
    return this.storage.getUiCulture();
  }

  /**
   * Set the uiLanguage
   *
   * @param {string} language
   * @param {Renderer2} renderer
   * @memberof LanguageService
   */
  setLanguage(language: string, renderer: Renderer2) {
    // save choosen language
    this.storage.setUiCulture(language);
    // set language on html-element
    renderer.setProperty(this.doc.documentElement, 'lang', language);
    // the lang to use, if the lang isn't available, it will use the current loader to get them
    this.translate.use(language);

    this.currentLanguage = language;
    moment.locale(this.currentLanguage);
  }

  /**
   * Parses a current-local date-string to a Date object
   *
   * @param {string} value
   * @returns {Date}
   * @memberof LanguageService
   */
  parseDate(value: string): Date {
    return moment(value, 'L').toDate();
  }

  /**
   * Returns the date representation according to the current local (eg. 22.10.1989)
   *
   * @param {Date} date
   * @returns {string}
   * @memberof LanguageService
   */
  formatDate(date: Date): string {
    if (!date) {
      return '';
    }
    return moment(date).format('L');
  }

  /**
   * Returns the time representation according to the current local (eg. 16:45 or 4:45 PM)
   *
   * @param {Date} date
   * @returns {string}
   * @memberof LanguageService
   */
  formatTime(date: Date): string {
    if (!date) {
      return '';
    }
    return moment(date).format('LT');
  }

  /**
   * Returns the name of the weekday in the current local (eg. Freitag)
   *
   * @param {Date} date
   * @returns
   * @memberof LanguageService
   */
  formatWeekday(date: Date) {
    return moment(date).format('dddd');
  }

  /**
   * Returns the abbreviated name of the weekday in the current local (eg. Fr.)
   *
   * @param {Date} date
   * @returns
   * @memberof LanguageService
   */
  formatWeekdayShort(date: Date) {
    return moment(date).format('ddd');
  }

  getWeekNumber(date: Date) {
    return moment(date).format('w');
  }

  getMonthString(date: Date) {
    return moment(date).format('MMMM');
  }

  /**
   * Returns the short name of a weekday (eg. Mo)
   *
   * @param {number} weekday
   * @returns {string}
   * @memberof LanguageService
   */
  getWeekdayShortName(weekday: number): string {
    return moment.weekdaysShort(weekday);
  }

  /**
   * Returns the full name of a weekday (eg. Montag)
   *
   * @param {number} weekday
   * @returns {string}
   * @memberof LanguageService
   */
  getWeekdayFullName(weekday: number): string {
    return moment.weekdays(weekday);
  }

  /**
   * Returns the short name of a month (eg. Apr.)
   *
   * @param {number} month
   * @param {number} [year]
   * @returns {string}
   * @memberof LanguageService
   */
  getMonthShortName(month: number, year?: number): string {
    return moment.monthsShort(month - 1);
  }

  /**
   * Returns the full name of a month (eg. Juni)
   *
   * @param {number} month
   * @returns {string}
   * @memberof LanguageService
   */
  getMonthFullName(month: number): string {
    return moment.months(month - 1);
  }

  /**
   * Returns date as string (eg. Donnerstag, 20. Juni 2019)
   *
   * @param {Date} date
   * @returns {string}
   * @memberof LanguageService
   */
  getDayAriaLabel(date: Date): string {
    return moment(date).format('dddd, LL');
  }

  /**
   * Returns the representation of a date according to the current local (eg. mm/dd/yyyy)
   *
   * @returns {Promise<string>}
   * @memberof LanguageService
   */
  getDateFormat(): Promise<string> {
    const that = this;
    return new Promise<string>((resolve, reject) => {
      if (that.currentDateFormat !== undefined) {
        resolve(that.currentDateFormat);
        return;
      }
      this.translate.get('YEAR_CHAR').subscribe((y) => {
        this.translate.get('MONTH_CHAR').subscribe((m) => {
          this.translate.get('DAY_CHAR')
            .toPromise()
            .then((d) => {
              const format = moment(new Date(1999, 11, 31)).format('L');
              that.currentDateFormat = format.replace('1999', y + y + y + y).replace('12', m + m).replace('31', d + d);
              resolve(that.currentDateFormat);
              return;
            });
        });
      });
    });
  }
}
