// AoT requires an exported function for factories
export function HttpLoaderFactory(http: HttpClient) {
  return new TranslateHttpLoader(http, AppConfigService.translationsPath);
}

export function AppConfigFactory(http: HttpClient, appConfig: AppConfigService): () => Promise<void> {
  return () => appConfig.load()
    .then(() => {
      const params = GetUrlTokenParams();
      if (params.access_token !== null || params.code !== null) {
        //self construct service because appConfig.load() is a prerequisite
        const loginHandler = new LoginHandlerService(http, new StorageService());
        return loginHandler.handleTokenResponse(params);
      }
      return Promise.resolve();
    });
}

/**
 * Retrurns token related url params
 *
 * @export
 * @return {{ access_token: string, code: string }}
 */
export function GetUrlTokenParams(): { access_token: string, code: string } {
  const params: { access_token: string, code: string } = { access_token: null, code: null };
  const args = window.location.search;
  if (args) {
    args.replace('?', '').split('&').forEach(arg => {
      var parts = arg.split('=');
      params[parts[0]] = parts[1];
    });
  }
  return params;
}

