import { Component, OnInit, Input, Output, EventEmitter, ElementRef, ViewChild, ChangeDetectionStrategy } from '@angular/core';
import { StringHelper } from '../../../../shared/utils/string-helper';
import { ITimeSpan, ITimeSlot, ITimeBlock, IRoomScheduleInfo, IDisplayItem } from './room-allocation-table.component';
import { ScheduleItem } from '../room-schedule-item/room-schedule-item.component';
import { OccupancyType } from 'src/app/shared/models/occupancy';
import { ICreateReservationParams } from '../create-reservation-dialog/create-reservation-dialog-base.component';
import { ResourceType } from 'src/app/shared/models/resource-type';
import { TranslateService } from '@ngx-translate/core';
import { RoomService } from 'src/app/shared/services/rest/room.service';
import { ResourceTableRow } from 'src/app/shared/models/resource-table-row';
import { Constants } from 'src/app/shared/models/constants.model';
import { time } from 'console';

@Component({
  selector: 'app-room-allocation-desktop',
  templateUrl: './room-allocation-desktop.component.html',
  styleUrls: ['./room-allocation-desktop.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RoomAllocationDesktopComponent implements OnInit {

  @Input() model: AllocationTableModel;

  @Input() openResourceCalendarText: string;

  @Input() openResourceInfoText: string;

  /**
   * Date of the displayed day
   *
   * @type {Date}
   * @memberof RoomAllocationMobileComponent
   */
  @Input() baseDate: Date;

  @Output() openRoomInfo = new EventEmitter<number>();

  @Output() openSchedule = new EventEmitter<IRoomScheduleInfo>();

  /**
   * Event raised on click on "create new"
   *
   * @memberof RoomScheduleItemComponent
   */
  @Output() createReservation = new EventEmitter<ICreateReservationParams>();

  /**
   * Event raised when there is time conflict for the current data + time value constellation
   *
   * @memberof RoomScheduleItemComponent
   */
  @Output() timelineReservationConflicted = new EventEmitter<ITimeSpan>();
  @Output() timelineNotReservable = new EventEmitter<ITimeSpan>();
  @Output() timelineClosed = new EventEmitter<ITimeSpan>();

  @ViewChild('progressBar') progressBar: ElementRef;

  private displayTimeSpanStart = 5;

  private displayTimeSpan = 17;

  timeStream: number[];

  colspans: number[] = [1, 3, 3, 3, 3, 3, 1];

  constructor(
    private translate: TranslateService,
    protected room: RoomService
  ) { }

  ngOnInit() {
    this.timeStream = [6, 9, 12, 15, 18, 21];
  }

  get resourceType(): string {
    switch (this.model.resourceType) {
      case ResourceType.Raum:
        return 'ROOM';
      case ResourceType.Gerät:
        return 'DEVICE';
      default:
        throw Error(`Support for type '${this.model.resourceType}' not implemented`);
    }
  }

  /**
   * checks if the items of a ressource is vacant and open for booking
   * @param item items to check for a possible free time slot
   * @returns {boolean}
   */
  hasAnyFreeSlot(item: ScheduleItem[]) {
    let retVal = item.some(i => (i.occupancyType === OccupancyType.Reservable || i.occupancyType === OccupancyType.Unavailable));
    return retVal;
  }

  /**
   * have to check if all items except the last one are blocked because the last one can be a free slot and seems consistent with the rest
   * @param items items to check if the timeline is completely closed
   * @returns {boolean}
   */
  areAllExceptLastBlocked(items: ScheduleItem[]): boolean {
    if (!Array.isArray(items) || items.length < 2) { return false; }
    return items
      .every(i => i.occupancyType === OccupancyType.Blocker);
  }

  warningClass(item: IDisplayItem): string {
    return item.isBookable ? 'text-warning' : 'text-danger';
  }

  /**
    * format time (eg. 15:00)
    *
    * @param {number} hour
    * @param {number} min
    * @returns
    * @memberof RoomAllocationComponent
    */
  getTimeString(hour: number, min: number): string {
    return StringHelper.formatTime(hour, min);
  }

  /**
    * format timespan (eg. 13:00 -  17:45)
    *
    * @param {ITimeSlot} slot
    * @returns
    * @memberof RoomAllocationComponent
    */
  getTimeSlotTooltip(slot: ITimeSlot): string {
    const sep = '#';

    if(slot.inUse)
    {
      const timespan = StringHelper.formatTimeSpan(slot.timeSpan.fromHour, slot.timeSpan.fromMin, slot.timeSpan.toHour, slot.timeSpan.toMin, sep);
      const occupiedPhrase = this.translate.instant('OCCUPIED');
      const fromPhrase = this.translate.instant('TIME_FROM');
      const toPhrase = this.translate.instant('TIME_TO');

      return `${occupiedPhrase} ${fromPhrase.toLowerCase()} ${timespan.replace(sep, ` ${toPhrase.toLowerCase()} `)}`;
    }
    else if(slot.closed)
    {
      return this.translate.instant('NOT_AVAILABLE');
    }
    else
    {
      switch(slot.reservationRightId)
      {
         case Constants.ReservationsRecht.Reservable:
          return this.translate.instant('TIMESPAN_FREE');
         case Constants.ReservationsRecht.ProvReservable:
          return this.translate.instant('TIMESPAN_PROVISIONALY_BOOKABLE');
         case Constants.ReservationsRecht.Requestable: 
          return this.translate.instant('TIMESPAN_REQUESTABLE');
         case Constants.ReservationsRecht.Visible:
          return this.translate.instant('TIMESPAN_FREE_NOT_BOOKABLE');
         default:
          return this.translate.instant('TIMESPAN_FREE_NOT_BOOKABLE');
      }
    }
    
  }

  getTimeSlotStyleClass(slot:ITimeSlot): string {
    if(slot.closed)
    {
      return 'progress-closed';
    } 
    else if(slot.inUse)
    {
      return 'progress-occupied';
    }
    else
    {
      return this.getStyleClassFromReservationRight(slot.reservationRightId);
    }
  }

  getStyleClassFromReservationRight(reservationRightId:number): string
  {
    switch(reservationRightId)
      {
         case Constants.ReservationsRecht.Reservable:
          return 'progress-reservable';
         case Constants.ReservationsRecht.ProvReservable:
          return 'progress-conditionally-reservable';
         case Constants.ReservationsRecht.Requestable: 
          return 'progress-requestable';
         case Constants.ReservationsRecht.Visible:
          return 'progress-free-not-reservable';
         default:
          return 'progress-free-not-reservable';
      }
  }

  /**
   * transforms a list of truthy + falsy values to 1 or 0 string respectively
   * @param boolList a list of truthy + falsy values to transform
   * @returns {string[]}
   */
  toFlagSet(boolList) {
    return boolList.map(li => Boolean(li) === true ? '1' : '0').join('');
  }

  /**
   * create list of time blocks
   *
   * @returns {ITimeBlock[]}
   * @memberof RoomAllocationComponent
   */
  getTimeLine(scheduleItems: ScheduleItem[]): ITimeBlock[] {
    if (scheduleItems === null) {
      return [];
    }

    const maxHour = this.displayTimeSpanStart + this.displayTimeSpan;
    // init
    const blocks = new Array<ITimeBlock>(maxHour);
    for (let i = this.displayTimeSpanStart; i <= maxHour; i++) {
      blocks[i] = ({ hour: i, events: [] });
    }

    scheduleItems.forEach(x => {
      const alloc = this.getTimeSlot(
        x.from.getHours(),
        x.from.getMinutes(),
        x.to.getHours(),
        x.to.getMinutes(),
        x.occupancyType == OccupancyType.Occupancy ? true : false, // inUse
        x.occupancyType == OccupancyType.Blocker ? true : false, // closed
        x.reservationRightId
      );

      // discard when end time is before timeline start time
      if (alloc.timeSpan.toHour < this.displayTimeSpanStart ||
        alloc.timeSpan.fromHour >= maxHour) {
        return;
      }

      // adjust offsets
      if (alloc.timeSpan.fromHour < this.displayTimeSpanStart) {
        alloc.timeSpan.fromHour = this.displayTimeSpanStart;
      }

      if (alloc.timeSpan.toHour > maxHour) {
        alloc.timeSpan.toHour = maxHour;
      }
      if (alloc.timeSpan.toHour === maxHour) {
        alloc.timeSpan.toMin = 0;
      }

      // add
      blocks[alloc.timeSpan.fromHour].events.push(alloc);
    });

    return blocks.slice(this.displayTimeSpanStart, maxHour);
  }

  /**
   * create a ITimeSlot object
   *
   * @private
   * @param {number} fromHour
   * @param {number} fromMin
   * @param {number} toHour
   * @param {number} toMin
   * @param {boolean} [inUse=false]
   * @returns {ITimeSlot}
   * @memberof RoomAllocationDesktopComponent
   */
  private getTimeSlot(fromHour: number, fromMin: number, toHour: number, toMin: number, inUse: boolean, closed: boolean, reservationRightId: number ): ITimeSlot 
  {
    const timeSpan : ITimeSpan = {fromHour: fromHour, fromMin: fromMin, toHour: toHour, toMin: toMin};
    return { timeSpan: timeSpan, inUse: inUse, closed: closed, reservationRightId: reservationRightId};
  }

  /**
   * Calculate the distance from left border of progrssbar-frame
   *
   * @param {ITimeSpan} span
   * @returns {string}
   * @memberof RoomAllocationDesktopComponent
   */
  showTimeStreamLeft(span: ITimeSpan): string {
    const timespanMinutesStart = span.fromHour * 60 + span.fromMin;
    let timeSpanStartPercent =  this.roundMinutesToTimeStreamPercent(timespanMinutesStart);
    return timeSpanStartPercent + '%';
  }

  showTimeStreamWidth(span: ITimeSpan): string {
    // end - start to get a seamless timestream coverage
    const timespanMinutesStart = span.fromHour * 60 + span.fromMin;
    const endtimeMinutes = (span.toHour * 60 + span.toMin);
    let widthInPercent = this.roundMinutesToTimeStreamPercent(endtimeMinutes) - this.roundMinutesToTimeStreamPercent(timespanMinutesStart);
    return widthInPercent + '%';
  }

  private roundMinutesToTimeStreamPercent(minutes: number): number
  {
    const calcBase = minutes - (this.displayTimeSpanStart) * 60;
    return Math.round(calcBase / (this.displayTimeSpan * 60) * 100);
  }

  zebra(index: number): string {
    return index % 2 === 0 ? 'bg-light' : '';
  }

  needSpace(index: number): boolean {
    return index < 21;
  }

  /**
   * handle click on "open roominfo" button
   *
   * @param {IDisplayItem} item
   * @memberof RoomAllocationDesktopComponent
   */
  onOpenRoomInfo(item: IDisplayItem, event: MouseEvent) {
    event.preventDefault();
    this.openRoomInfo.emit(item.resourceId);
  }

  /**
   * handle click on "open room schedule" button
   *
   * @param {IDisplayItem} item
   * @memberof RoomAllocationDesktopComponent
   */
  onOpenSchedule(item: IDisplayItem) {
    this.openSchedule.emit({
      roomId: item.resourceId,
      designation: item.designation,
      isBookable: item.isBookable,
      hasWarnings: Boolean(item.warning),
      statusInfo: item.statusInfo,
      resRight: item.resRight,
      bookableFlags: this.toFlagSet([item.isRessourceAvailable, item.isBookingAllowed])
    });
  }

  onClickTimeline(event: MouseEvent, item: IDisplayItem, timeSlot?:ITimeSpan) {  
    // relative mouse position click
    let width:number, left:number, timeSpan:number, timeSpanStart:number
    if(timeSlot != null)
    {
      let clickedTimeSpanMinutes = this.getTimeSpanLengthInMinutes(timeSlot);
      width = this.progressBar.nativeElement.clientWidth * (clickedTimeSpanMinutes/(this.displayTimeSpan*60)); // take percentage of complete bar
      left = event.offsetX;
      timeSpan = clickedTimeSpanMinutes/60;
      timeSpanStart = timeSlot.fromHour;
    }
    else{
      width = this.progressBar.nativeElement.clientWidth;
      left = event.offsetX;
      timeSpan = this.displayTimeSpan;
      timeSpanStart = this.displayTimeSpanStart;
    }
    
    // calc time
    const decimalHour = (timeSpan * (left / width)) + timeSpanStart;
    let startHour = Math.floor(decimalHour);
    const startMinute = Math.round(60 * (decimalHour % 1));

    // round to 15 min
    let startQuarterHour = Math.round(startMinute / 15) * 15;
    if (startQuarterHour === 60) {
      startQuarterHour = 0;
      startHour++;
    }

    // create from date
    const date = this.baseDate;
    const from = new Date(date.getFullYear(), date.getMonth(), date.getDate(), startHour, startQuarterHour, 0, 0);

    // raise event
    this.createReservation.emit({
      idReservation: null,
      idRessource: item.resourceId,
      from: from,
      to: null,
      statusInfo: item.statusInfo,
      reservationRight: item.resRight
    });
  }

  private getTimeSpanLengthInMinutes(timeSpan:ITimeSpan):number{
    if(timeSpan.fromHour == timeSpan.toHour) return timeSpan.toMin - timeSpan.fromMin;
    return(60-timeSpan.fromMin + 60*(timeSpan.toHour - timeSpan.fromHour - 1)+timeSpan.toMin)
  }

  onCreateReservationByButton(item: IDisplayItem) {

    const bd = this.baseDate;
    const BASE_MINUTES = 15;
    const nd = new Date();
    const fromDate = new Date(
      bd.getFullYear(),
      bd.getMonth(),
      bd.getDate(),
      nd.getHours(),
      Math.round((nd.getMinutes() + 5 ) / 5) * 5);

    const toDate = new Date(
      bd.getFullYear(),
      bd.getMonth(),
      bd.getDate(),
      nd.getHours(),
      Math.round((nd.getMinutes() + 5 + BASE_MINUTES) / 5) * 5);

    // figure out the best time free time slot to load forms with
    const nowTimestamp = fromDate.getTime();
    const nowTillEndtimeDelta = 60 * (BASE_MINUTES + 5) * 1000; // 20min time frame minimum
    const allReservables = item.scheduleItems.filter(si => si.occupancyType === OccupancyType.Reservable);
    const allEndingInFuture = allReservables
      .filter(si => si.to.getTime() > nowTimestamp)
      .sort((li, ri) => li.to.getTime() - ri.to.getTime());
    const bestFuture = allEndingInFuture.find(i => i.to.getTime() - nowTimestamp >= nowTillEndtimeDelta) ||
      allEndingInFuture.slice(-1)[0] ||
      allReservables.slice(-1)[0];

    // raise create reservation event
    this.createReservation.emit({
      idReservation: null,
      idRessource: item.resourceId,
      from: nowTimestamp < bestFuture.from.getTime() ? bestFuture.from : new Date(nowTimestamp),
      to: toDate > bestFuture.to ? bestFuture.to : toDate,
      statusInfo: item.statusInfo,
      reservationRight: item.resRight
    });
  }

  /**
   * Last additional column in header must have colspan="2" (space for calendar button)
   *
   * @param {number} index
   * @returns {boolean}
   * @memberof RoomAllocationDesktopComponent
   */
  isLastHeaderCell(index: number): boolean {
    return index + 1 === this.model.additionalColums.length;
  }

  onClickBlockOnTimeline(event: MouseEvent, item: IDisplayItem, clickedSlot: ITimeSlot) {
    console.log('onClickBlockOnTimeline', clickedSlot, item);

    if(clickedSlot === undefined || clickedSlot === null) {
      console.warn('onClickBlockOnTimeline: clickedSlot is undefined or null');
      this.timelineClosed.emit();
      return;
    }

    if(clickedSlot.inUse)
    {
      this.timelineReservationConflicted.emit(clickedSlot.timeSpan);
    }
    else if(clickedSlot.closed)
    {
      this.timelineClosed.emit(clickedSlot.timeSpan);
    }
    else if(clickedSlot.reservationRightId == Constants.ReservationsRecht.None 
      || clickedSlot.reservationRightId == Constants.ReservationsRecht.Visible) 
    {
      this.timelineNotReservable.emit(clickedSlot.timeSpan);
    }
    else 
    {
      this.onClickTimeline(event, item, clickedSlot.timeSpan);
    }
  }
}

export class AllocationTableModel {
  public mainColumnTitle: string;
  public additionalColums: ResourceTableRow[];
  public calendarButtonText: string;
  public displayItems: IDisplayItem[];
  public resourceType: ResourceType;
}

/**
 * Row model for AllocationTableModel
 *
 * @export
 * @class AllocationTableItem
 */
export class AllocationTableItem {
  public id: string;
  public designation: string;
  public additionalColumsData: ResourceTableRow[];
  public warning: string;
}
